(window.NTDATA=window.NTDATA||{});(NTDATA.rbo=NTDATA.rbo||{}).ex={"1":{"1":"Вот имена сынов Израилевых, пришедших с Иаковом в Египет (каждый пришел со своей семьей):","2":"Рувим, Симеон, Левий, Иуда,","3":"Иссахар, Завулон, Вениамин,","4":"Дан, Неффалим, Гад и Асир.","5":"Всего их, потомков Иакова, было семьдесят человек – с Иосифом, который к тому времени уже жил в Египте.","6":"Иосиф умер, умерли его братья и все их поколение.","7":"А сыны Израилевы были плодовиты, их становилось все больше, они стали многочисленны и сильны, заполонили всю страну.","8":"На престол Египта взошел новый царь, который не знал Иосифа.","9":"Он сказал своим людям: «Смотрите, как много стало сынов Израилевых! Они сильнее нас.","10":"Надо что – то придумать, чтобы их не стало еще больше, а то, если будет война, они соединятся с нашими врагами, поднимут восстание и уйдут из нашей страны».","11":"Чтобы изнурить сынов Израилевых тяжкими работами, египтяне поставили над ними надсмотрщиков и заставили строить для фараона два города со складами – Питом и Раамсес.","12":"Однако чем сильнее притесняли сынов Израилевых, тем больше их становилось. Ужас перед ними охватил египтян;","13":"они стали безжалостно принуждать сынов Израилевых к тяжким работам.","14":"Они превратили всю жизнь сынов Израилевых в горький и тяжелый труд: те месили глину, делали кирпичи, трудились в поле – их принуждали к этим работам без всякой жалости.","15":"Египетский царь велел повитухам – еврейкам (одну звали Шифра, а другую – Пуа ):","16":"«Когда будете принимать роды у евреек, смотрите, кто родится. Если мальчик – убивайте, а если девочка – пусть живет».","17":"Но повитухи боялись Бога и потому не слушались царского приказа: оставляли мальчиков в живых.","18":"Царь вызвал их к себе и спросил: «Почему вы оставляете мальчиков в живых?» –","19":"«Еврейки не египтянки, – отвечали фараону повитухи, – они крепкие. Повитуха прийти не успеет, а еврейка уже родила».","20":"За это Бог воздал повитухам добром. Народ же Израилев становился все многочисленнее и сильнее.","21":"(За то, что повитухи боялись Бога, Бог даровал их семействам благоденствие.)","22":"Тогда фараон отдал своему народу такой приказ: «Всех мальчиков, которые у них родятся, бросайте в Нил. Девочек оставляйте в живых»."},"2":{"1":"В ту пору один из потомков Левия взял себе жену, тоже из потомков Левия.","2":"У них родился сын. Мать увидела, как он хорош, и три месяца прятала его.","3":"А когда прятать стало уже невозможно, она взяла ковчег, сделанный из папируса, обмазала его асфальтом и смолой, положила в него младенца, и оставила на берегу Нила, в тростнике.","4":"Сестра ребенка стояла поодаль и смотрела, что будет дальше.","5":"И вот к Нилу пришла искупаться дочь фараона в сопровождении служанок. Она заметила ковчег в зарослях тростника, велела рабыне его принести,","6":"открыла и увидела младенца. Младенец плакал, ей стало жаль его. «Это еврейский ребенок», – сказала дочь фараона.","7":"Сестра ребенка спросила у нее: «Может, я пойду позову кормилицу – еврейку, чтобы она выкормила для тебя этого младенца?» –","8":"«Сходи», – сказала дочь фараона. Девочка пошла, привела мать ребенка,","9":"и дочь фараона сказала ей: «Возьми его и выкорми для меня. Я тебе заплачу ». Женщина взяла младенца и выкормила его,","10":"а когда он подрос, привела его к дочери фараона. Та усыновила мальчика и дала ему имя Моисей, сказав: «Это означает, что я вынула его из воды».","11":"Шло время. Моисей вырос. Он пришел к своим братьям, евреям, и увидел их тяжкий труд. Он увидел, как египтянин бьет брата его, еврея.","12":"Оглянулся Моисей по сторонам – никого рядом не было. Он убил египтянина, а труп зарыл в песок.","13":"На следующий день Моисей снова туда пришел и увидел, как дерутся друг с другом два еврея. «Зачем ты бьешь своего товарища?» – спросил Моисей у обидчика.","14":"Тот ответил: «А кто тебя сделал над нами начальником и судьей? Ты что, и меня хочешь убить, как убил египтянина?» Страшно стало Моисею: он понял, что все обнаружилось.","15":"Фараон, узнав о происшедшем, хотел казнить Моисея. Но Моисей бежал от фараона и поселился в стране мидьянитян. Когда он сидел у колодца,","16":"туда подошли семь дочерей мидьянского жреца, чтобы начерпать воды и наполнить поилки для отцовской отары.","17":"Подошедшие пастухи стали гнать их прочь, но Моисей встал и заступился за девушек, а потом напоил их овец.","18":"Когда девушки вернулись к своему отцу, Реуэлу, тот спросил: «Что вы сегодня так скоро?» –","19":"«Какой – то египтянин, – ответили они, – заступился за нас перед пастухами, а потом начерпал нам воды и напоил овец». –","20":"«Так где же он? – спросил отец. – Почему вы не позвали его? Зовите, пусть поест с нами вместе».","21":"Моисей решил остаться у мидьянитянина. Тот отдал Моисею в жены свою дочь Циппору ,","22":"и у них родился сын. Моисей дал сыну имя Гершом, сказав: «Это означает, что я стал переселенцем в земле чужой».","23":"Много времени прошло. Царь египетский умер. Сыны Израилевы стонали от тяжкой работы, взывали о помощи – и стон их дошел до Бога.","24":"Услышал их стоны Бог – и вспомнил Свой договор с Авраамом, Исааком и Иаковом.","25":"Бог обратил Свой взор на сынов Израилевых! Бог озаботился их судьбой!"},"3":{"1":"Моисей пас овец своего тестя, мидьянского жреца Итро. Однажды он ушел со стадом далеко в пустыню и оказался близ Божьей горы, Хорива.","2":"Там ему явился ангел Господень – как огонь, горящий внутри куста. Моисей увидел: куст горит, но не сгорает.","3":"«Пойду посмотрю на это чудо поближе, – подумал он, – почему не сгорает куст?»","4":"Увидел Господь, что Моисей подошел посмотреть, – и воззвал Бог к Моисею из горящего куста: «Моисей, Моисей!» – «Да!» – отозвался тот.","5":"Бог сказал: «Не приближайся. Сними сандалии: место, где ты стоишь, – свято.","6":"Я Бог твоих отцов, – сказал Он Моисею. – Я Бог Авраама, Бог Исаака, Бог Иакова». Моисей закрыл лицо: он боялся взглянуть на Бога.","7":"Господь сказал: «Я вижу, как страдает Мой народ в Египте. Я слышу, как он взывает о помощи – надсмотрщики притесняют его! Я знаю, как измучен Мой народ.","8":"И Я сошел, чтобы спасти его от египтян, чтобы увести его из Египта в землю хорошую и обширную, источающую молоко и мед, – в страну ханаанеев, хеттов, амореев, периззеев, хиввеев и евусеев.","9":"Стон сынов Израилевых, их зов о помощи дошел до Меня: Я увидел, как угнетают их египтяне.","10":"Иди же – Я посылаю тебя к фараону: уведи Мой народ, сынов Израилевых, из Египта!»","11":"Но Моисей сказал: «Кто я такой, чтобы пойти к фараону и увести сынов Израилевых из Египта?»","12":"Бог ответил ему: «Я буду с тобой. И вот знак того, что ты Мой посланник: когда ты уведешь Мой народ из Египта, вы придете и совершите служение Богу на этой горе».","13":"Моисей спросил: «Вот, я приду к сынам Израилевым и скажу им: „Меня к вам послал Бог ваших отцов\". А если они спросят: „Как Его имя?\", – что мне ответить?»","14":"Бог сказал Моисею: «Я ТОТ, КТО Я ЕСТЬ. Так и ответь сынам Израилевым: „Меня послал к вам Тот, чье имя – ЭХЙЕ (Я ЕСТЬ)\"».","15":"И еще Бог сказал Моисею: «Ответь сынам Израилевым, что тебя послал ЯХВЕ (ГОСПОДЬ), Бог их отцов – Авраама, Исаака и Иакова. Это имя Мое навеки; это имя Мое из рода в род.","16":"Иди и созови старейшин Израиля. Передай им, что Господь, Бог их отцов, Бог Авраама, Исаака и Иакова, явился тебе и сказал: „Я обратил на вас Свой взор и увидел, как поступают с вами египтяне.","17":"И Я возвещаю вам, что уведу вас из египетского рабства в землю ханаанеев, хеттов, амореев, периззеев, хиввеев и евусеев – в землю, что источает молоко и мед\".","18":"Старейшины Израиля тебя послушают, пойдут вместе с тобою к египетскому царю, и вы ему скажете: „Нам явился Господь, Бог евреев. Позволь нам уйти в пустыню, на три дня пути, и принести там жертву Господу, нашему Богу\".","19":"Я знаю, что египетский царь станет вас удерживать – невзирая на мощь руки Моей!","20":"И Я занесу Свою руку над ним! Я сокрушу Египет чудесами невиданными – и тогда он вас отпустит.","21":"И Я сделаю так, что египтяне окажут вам милость – и вы уйдете из Египта не с пустыми руками.","22":"Ваши женщины попросят у своих соседок серебро, золото и одежду, вы нарядите своих сыновей и дочерей! Вы уйдете из Египта с богатой добычей»."},"4":{"1":"Но Моисей сказал: «А что если мне не поверят и не станут слушать – скажут: „Господь тебе не являлся!\"?» –","2":"«Что у тебя в руке?» – спросил Господь Моисея. Тот ответил: «Посох». –","3":"«Брось его на землю», – велел Господь. Моисей бросил. Посох превратился в змею, и Моисей кинулся прочь.","4":"«Протяни руку, возьми ее за хвост», – велел ему Господь. Моисей протянул руку, схватил змею – и в его руке она превратилась в посох.","5":"Господь сказал: «Это чтобы они поверили, что тебе и вправду явился Господь, Бог их отцов – Бог Авраама, Исаака и Иакова».","6":"«Сунь руку за пазуху», – велел Господь Моисею. Моисей сунул руку за пазуху. А когда вынул, рука была бела как снег – поражена проказой.","7":"«Снова сунь руку за пазуху, – велел ему Господь». Моисей вновь сунул руку за пазуху, а когда вынул, рука была как прежде – как здоровое тело.","8":"Господь сказал: «Если они тебе не поверят, если первое чудо не убедит их – их убедит второе чудо.","9":"А если они не поверят ни тому ни другому чуду и не станут тебя слушать – тогда зачерпни нильской воды, плесни на землю, и эта вода превратится в кровь».","10":"«О Владыка мой! – взмолился Моисей к Господу. – Я не красноречив. И прежде не умел я ладно говорить. Никогда не был я красноречив, не красноречив я и сейчас, когда Ты говоришь со мною, рабом Твоим. Я неискусен в слове и косноязычен».","11":"И сказал Господь: «Кто дал человеку уста? Кто делает немым или глухим? Кто делает зрячим или слепым? Я, Господь!","12":"Так иди же! Я буду с тобой, когда ты будешь говорить; Я Сам научу тебя, что сказать». –","13":"«О Владыка мой! – взмолился Моисей. – Пошли кого – нибудь другого – кого хочешь!»","14":"Тогда разгневался Господь на Моисея и сказал ему: «А твой брат, Аарон – левит? Я знаю, он говорить умеет! Он уже идет тебя встречать; он увидит тебя и обрадуется,","15":"а ты ему все объяснишь и передашь, что надо сказать. Я Сам буду с вами, когда вы станете говорить; Я Сам научу вас, что делать.","16":"Аарон будет говорить с народом вместо тебя и станет твоими устами: ты будешь его богом.","17":"И возьми с собою этот посох: с его помощью ты будешь творить чудеса».","18":"Придя домой, Моисей сказал своему тестю Итро: «Позволь мне вернуться в Египет, к братьям моим, посмотреть, живы ли они». – «Ступай с миром», – ответил ему Итро.","19":"Там, в Мидьяне, Господь сказал Моисею: «Возвращайся в Египет. Те, кто хотел тебя убить, уже умерли».","20":"Моисей посадил жену и детей на осла, взял с собою посох Божий и пошел в Египет.","21":"Господь сказал Моисею: «Я дал тебе силу творить чудеса. Когда вернешься в Египет, сотвори все эти чудеса перед фараоном. Я заставлю фараона упорствовать; он вас не отпустит.","22":"И тогда ты скажешь ему: „Господь говорит: Израиль – это Мой сын, Мой первенец.","23":"Я велел тебе:,Отпусти Моего сына совершить служение Мне`, – а ты не отпустил! За это Я убью твоего сына – первенца!\"»","24":"По дороге, на ночной стоянке, пришел к Моисею Господь и хотел его убить.","25":"Тогда Циппора взяла острый кремень, обрезала своему сыну крайнюю плоть и сказала, прикоснувшись к его ногам: «Ты мне жених через кровь!»","26":"И Господь отступил от него. («Жених через кровь» – так она сказала про обрезание.)","27":"Господь велел Аарону: «Иди в пустыню, навстречу Моисею!» Аарон пустился в путь и у горы Божьей встретился с Моисеем. Они расцеловались.","28":"Моисей передал Аарону, что сказал ему Господь, когда сделал его Своим посланцем, и какие чудеса Господь велел ему сотворить.","29":"Они пошли и собрали всех старейшин Израиля.","30":"Аарон передал им все, что Господь сказал Моисею, и совершил чудеса на глазах у всего народа.","31":"И люди поверили. Услышав, что Господь вспомнил о сынах Израилевых и увидел их страдания, они пали ниц."},"5":{"1":"Моисей и Аарон пришли к фараону и сказали ему: «Господь, Бог Израиля, говорит: отпусти Мой народ в пустыню, справить Мой праздник!»","2":"Но фараон ответил: «Кто такой этот Господь, чтобы я Его слушался и отпускал сынов Израилевых? Я этого Господа не знаю и сынов Израилевых не отпущу». –","3":"«Нам явился Бог евреев, – сказали Моисей и Аарон. – Разреши нам уйти в пустыню на три дня пути и принести жертвы Господу, нашему Богу, – а не то Он погубит нас чумой или мечом».","4":"Но царь сказал им в ответ: «Моисей и Аарон! Зачем вы отвлекаете свой народ от работы? Идите работать!","5":"Их так много, – сказал царь Моисею и Аарону, – и вы хотите, чтоб они бросили работу?»","6":"В тот же день фараон велел надсмотрщикам и старостам:","7":"«Впредь не давайте этому народу соломы для кирпичей, как раньше давали, – пусть сами идут и собирают солому.","8":"Но кирпичей с них спрашивайте столько же, сколько и прежде, убавлять не надо. А то они обленились и стали говорить: „Пойдем принесем жертвы нашему Богу\".","9":"Станет работа потяжелее – будут работать, а не слушать праздные речи!»","10":"Выйдя от фараона, надсмотрщики и старосты сказали евреям: «Фараон говорит: „Впредь не буду давать вам соломы.","11":"Сами собирайте солому, где хотите, а кирпичей делайте, сколько раньше делали\"».","12":"И стали евреи ходить по всему Египту и рвать на полях жнивье, вместо соломы.","13":"А надсмотрщики подгоняли: «Делайте каждый день столько же кирпичей, сколько делали прежде, когда у вас была солома!»","14":"Фараоновы надсмотрщики поставили над сынами Израилевыми старост – а теперь этих старост стали бить и спрашивать с них: «Почему не выполняете положенную работу? Чтоб делали столько же кирпичей, сколько прежде!»","15":"Старосты сынов Израилевых пошли к фараону жаловаться: «За что ты так поступаешь с нами, рабами твоими?","16":"Нам, рабам твоим, соломы не дают, а кирпичи велят делать! Нас, рабов твоих, избивают! Грех твоим людям так поступать!» –","17":"«Да вы просто обленились! – ответил им фараон. – Обленились и стали говорить: „Пойдем, принесем жертвы Господу!\"","18":"Ступайте работать. Соломы вы больше не получите, а кирпичей делайте, сколько положено!»","19":"Услышали старосты сынов Израилевых, что нужно делать столько же кирпичей, сколько и прежде, и поняли, что дела их плохи.","20":"Выйдя от фараона, они подошли к Моисею и Аарону, стоявшим в ожидании их,","21":"и сказали: «Пусть Господь увидит, что вы наделали, и будет вам судьей! Ведь это из – за вас фараон и его вельможи нас возненавидели. Вы даете им повод убить нас!» –","22":"«Владыка! – воззвал Моисей к Господу. – Зачем Ты мучишь этот народ? Зачем Ты послал меня сюда?","23":"Я пришел к фараону как Твой посланник – а народу стало только хуже! Ты не спас Свой народ!»"},"6":{"1":"Господь ответил: «Ты увидишь, что сделаю Я с фараоном! Под тяжестью руки Моей он отпустит евреев! Под тяжестью руки Моей он выгонит их из страны!»","2":"Бог сказал Моисею: «Я Господь!","3":"Я являлся Аврааму, Исааку и Иакову как Бог Всесильный, но Моего имени „Господь\" Я им не открыл.","4":"Я заключил с ними договор и обещал отдать им ханаанскую землю – страну, где они были чужаками.","5":"Ныне Я услышал, как стонут сыны Израилевы под игом египтян, и вспомнил про этот договор.","6":"Передай же сынам Израилевым: „Я Господь! Я уведу вас из египетской неволи, освобожу из рабства! Я вас избавлю: занесена Моя рука и страшны Мои кары!","7":"Я сделаю вас Моим народом и буду вашим Богом, и вы будете помнить, что это Я – Господь, Бог ваш, – вывел вас из египетской неволи.","8":"Я приведу вас в землю, которую обещал отдать Аврааму, Исааку и Иакову, и передам ее вам во владение. Я Господь!\"»","9":"Моисей передал эти слова сынам Израилевым, но те даже и слушать его не стали, от малодушия и от тяжести работ.","10":"Господь велел Моисею:","11":"«Иди к фараону, царю египетскому. Скажи ему, чтобы он разрешил сынам Израилевым уйти из его страны!» –","12":"«Уж если сыны Израилевы меня не слушают, – сказал Моисей Господу, – как же послушается меня фараон? Не умею я ладно говорить…»","13":"Господь говорил с Моисеем и Аароном. Он велел им идти к сынам Израилевым и к фараону, царю египетскому, чтобы вывести сынов Израилевых из Египта.","14":"Вот прародители их родов. Сыновья Рувима (Рувим – первенец Израиля): Енох, Паллу, Хецрон и Карми. От них пошли роды Рувимовы.","15":"Сыновья Симеона: Иемуэл, Ямин, Охад, Яхин, Цохар и Саул, сын ханаанеянки. От них пошли роды Симеоновы.","16":"Вот имена сыновей Левия, в порядке старшинства: Гершон, Кехат и Мерари. (Левий прожил сто тридцать семь лет.)","17":"Сыновья Гершона: Ливни и Шими со своими родами.","18":"Сыновья Кехата: Амрам, Ицхар, Хеврон и Уззиэл. (Кехат прожил сто тридцать три года.)","19":"Сыновья Мерари: Махли и Муши. Таковы роды левитов, в порядке старшинства.","20":"Амрам взял в жены Иохевед, свою тетку. Она родила ему сыновей: Аарона и Моисея. (Амрам прожил сто тридцать семь лет.)","21":"Сыновья Ицхара: Корей, Нефег и Зихри .","22":"Сыновья Уззиэла: Мисаил, Элцафан и Ситри .","23":"Аарон взял в жены Элишеву, дочь Амминадава, сестру Нахшона. Она родила ему сыновей: Надава, Авиуда, Элеазара и Итамара.","24":"Сыновья Корея: Ассир, Элкана и Авиасаф. От них пошли роды Кореевы.","25":"Элеазар, сын Аарона, взял себе в жены одну из дочерей Путиэла. Она родила ему сына Пинехаса. Таковы прародители левитских родов.","26":"Это им, Аарону и Моисею, Господь повелел вывести из Египта воинство сынов Израилевых.","27":"Это они, Моисей и Аарон, держали речь перед фараоном, царем египетским, чтобы вывести сынов Израилевых из Египта.","28":"Когда Господь, в Египте, говорил с Моисеем,","29":"Он сказал ему: «Я Господь! Все, что Я говорю тебе, передай фараону, царю египетскому». –","30":"«Не умею я ладно говорить, – ответил Моисей. – Разве послушается меня фараон?»"},"7":{"1":"И сказал ему Господь: «Я сделаю так, что ты будешь для фараона богом, а твой брат Аарон будет твоим пророком.","2":"Ты возвещай, что Я тебе повелю, а твой брат Аарон передаст фараону, чтобы тот отпустил сынов Израилевых из своей страны.","3":"Я заставлю фараона упорствовать. Я явлю в Египте множество чудес и знамений,","4":"но фараон не станет вас слушать. И вот тогда Я заставлю Египет познать всю тяжесть руки Моей! Я выведу из Египта Мое воинство, Мой народ – сынов Израилевых. Страшны Мои кары!","5":"Под тяжестью руки Моей узнают египтяне, кто такой Господь, – и Я уведу сынов Израилевых из – под их власти».","6":"Как повелел Господь Моисею и Аарону, так они и сделали.","7":"(Когда Моисей и Аарон говорили с фараоном, Моисею было восемьдесят лет, а Аарону – восемьдесят три года.)","8":"Господь сказал, обращаясь к Моисею и Аарону:","9":"«Когда фараон потребует от вас: „Покажите чудо!\", то вели Аарону бросить перед фараоном свой посох – и посох превратится в змею».","10":"Моисей и Аарон пришли к фараону и сделали, как повелел Господь: на глазах у фараона и его вельмож Аарон бросил на землю свой посох – и посох превратился в змею.","11":"Но фараон позвал своих мудрецов и колдунов, и они, эти египетские маги, с помощью волшебства своего, сделали то же самое:","12":"каждый бросил свой посох на землю и эти посохи превратились в змей. Да только посох Аарона проглотил все их посохи!","13":"Но фараон упорствовал: не стал слушать Моисея и Аарона (как и предсказывал Господь).","14":"Господь сказал Моисею: «Упрямится фараон: не хочет отпускать Мой народ.","15":"Завтра утром, когда фараон пойдет к реке, ступай ему навстречу. Встань перед ним на берегу Нила, держи в руке посох, что превращался в змею,","16":"и скажи фараону так: „Господь, Бог евреев, послал меня сказать тебе: отпусти Мой народ в пустыню – совершить служение Мне. Но ты все не слушаешься.","17":"И Господь говорит тебе: сейчас ты узнаешь, кто такой Господь! Я ударю по нильской воде посохом, и вода станет кровью.","18":"Умрут все рыбы в Ниле, а от реки пойдет такой смрад, что египтяне не смогут пить воду из нее!\"»","19":"Господь велел Моисею: «Скажи Аарону: „Возьми свой посох, взмахни над водами Египта – над реками, над рукавами Нила, над озерами и водоемами – и вода в них станет кровью. По всему Египту будет кровь – кровь на дереве, кровь на камне!\"»","20":"Моисей и Аарон сделали, как повелел Господь. Поднял Аарон посох, ударил им по нильской воде на глазах у фараона и его вельмож – и нильская вода стала кровью.","21":"Все рыбы в Ниле умерли, а от Нила пошел такой смрад, что египтяне не могли больше пить из него воду. По всему Египту была кровь.","22":"Но то же самое, с помощью волшебства своего, сделали и египетские маги. И фараон продолжал упорствовать: не стал слушать Моисея и Аарона (как и предсказывал Господь).","23":"Повернулся фараон и пошел к себе во дворец, не обращая внимания на происшедшее.","24":"А египтяне стали копать вокруг Нила колодцы, потому что нильскую воду нельзя было пить.","25":"Минуло семь дней с тех пор, как Господь поразил Нил."},"8":{"1":"Господь велел Моисею: «Иди к фараону, скажи ему: „Господь говорит: отпусти Мой народ – совершить служение Мне!","2":"Если не отпустишь, Я нашлю на твою страну жаб.","3":"Весь Нил будет кишеть жабами: они выйдут из реки и заполнят твой дворец, залезут в твою спальню, к тебе в постель, заполнят дома твоих вельмож и всего твоего народа, забьются в ваши печи и в ваши квашни.","4":"Жабы придут и к тебе самому, и к твоему народу, и к твоим вельможам!\"»","5":"Господь велел Моисею: «Скажи Аарону, пусть занесет он свой посох над всеми реками Египта, над рукавами Нила и над озерами – и нашлет жаб на землю египетскую».","6":"Простер Аарон руку над водами Египта – и вышли из них жабы, и заполнили всю землю египетскую.","7":"Но то же самое, с помощью волшебства своего, сделали и маги – наслали жаб на землю египетскую.","8":"Фараон позвал Моисея и Аарона и сказал им: «Попросите Господа, пусть Он избавит меня и мой народ от этих жаб! Тогда я отпущу ваш народ принести жертвы Господу».","9":"Моисей ответил: «Я буду просить за тебя, за твоих вельмож и за твой народ. Назначь срок, к которому вы и ваши дома должны быть избавлены от жаб. Жабы останутся лишь в Ниле». –","10":"«К завтрашнему же дню!» – сказал фараон. «Как ты сказал, так и будет, – ответил Моисей. – Это чтобы ты понял, что нет никого, равного Господу, Богу нашему.","11":"Жабы оставят и тебя, и твой дворец, и твоих вельмож, и твой народ; они будут только в Ниле».","12":"Когда Моисей и Аарон вышли от фараона, Моисей попросил Господа уничтожить всех жаб, которых Господь наслал на Египет.","13":"Господь выполнил просьбу Моисея. Умерли все жабы: в домах, во дворах и в полях.","14":"Дохлых жаб собирали в кучи, и по всей стране стоял смрад.","15":"Но фараон, увидев, что беда миновала, снова стал упрямиться: не послушался он Моисея и Аарона (как и предсказывал Господь).","16":"Господь велел Моисею: «Скажи Аарону, пусть занесет он свой посох и ударит им по пыли, покрывающей землю, – и по всему Египту пыль превратится в мошек».","17":"Моисей и Аарон так и сделали. Занес Аарон свой посох, ударил им по пыли – и тотчас людей и скот облепили мошки. По всему Египту пыль, покрывавшая землю, превратилась в мошек.","18":"Маги тоже попытались, с помощью своего волшебства, произвести на свет мошек – но не вышло у них! И люди и скот были облеплены мошками.","19":"«Это перст Божий!» – сказали маги фараону. Но фараон по прежнему упорствовал и не слушался (как и предсказывал Господь).","20":"Господь сказал Моисею: «Завтра, рано утром, когда фараон пойдет к реке, снова стань перед ним и скажи: „Господь говорит: отпусти Мой народ, чтобы он совершил служение Мне!","21":"А если не отпустишь, Я нашлю оводов – и на тебя, и на твоих вельмож, и на весь твой народ, и на твой дворец. Дома всех египтян и даже земля у египтян под ногами – все будет кишеть оводами!","22":"А землю Гошен Я пощажу: там живет Мой народ – и там оводов не будет. Это чтобы ты знал, что Я, Господь, пребываю на этой земле!","23":"Свой народ Я избавлю от беды, а твой народ – нет. Это знамение будет явлено завтра!\"»","24":"Так и сделал Господь. Тучи оводов заполнили дворец фараона, дома его вельмож и весь Египет. Погибала страна от оводов.","25":"Фараон позвал Моисея и Аарона и сказал им: «Идите, принесите жертвы своему богу здесь, на нашей земле».","26":"Но Моисей ответил: «Мы не можем этого сделать. Жертвоприношение, которое мы совершаем Господу, нашему Богу, египтяне сочтут мерзостью. Если мы совершим такое жертвоприношение на глазах у египтян, они побьют нас камнями!","27":"Мы должны уйти в пустыню на три дня пути и там принести жертвы Господу, нашему Богу, – так, как Он скажет нам». –","28":"«Я отпускаю вас, – сказал фараон. – Ступайте, приносите в пустыне жертвы своему богу Господу, только далеко не уходите. И попросите за меня!»","29":"Моисей ответил: «Когда я от тебя выйду, то попрошу Господа, и завтра же все вы будете избавлены от оводов – и фараон, и вельможи, и весь египетский народ. Но пусть фараон нас больше не обманывает, пусть не препятствует нашему народу пойти и принести жертвы Господу».","30":"Вышел Моисей от фараона, попросил Господа,","31":"и Господь исполнил его просьбу: избавил и фараона, и его вельмож, и весь египетский народ от оводов. Ни одного овода не осталось.","32":"Но фараон снова стал упрямиться: не отпустил он сынов Израилевых."},"9":{"1":"Господь велел Моисею: «Иди к фараону, скажи ему: „Господь, Бог евреев, говорит: отпусти Мой народ – совершить служение Мне!","2":"А если не отпустишь, если будешь их удерживать,","3":"то на весь твой скот в поле – на лошадей, ослов и верблюдов, на коров, овец и коз – обрушится рука Господа: начнется страшный мор!","4":"А скот сынов Израилевых Господь пощадит – не то, что скот египтян! У сынов Израилевых ни одно животное не падет!\"»","5":"И Господь назначил срок: «Завтра Господь так сделает по всей стране!»","6":"Так и сделал Господь на следующий день: у египтян пал весь скот, а у сынов Израилевых ни одно животное не пало.","7":"Фараон послал проверить – и в самом деле, ни одно животное не пало у сынов Израилевых! Но фараон по – прежнему упрямился: не отпускал сынов Израилевых.","8":"Господь велел Моисею и Аарону: «Наберите по пригоршне золы из печи, и пусть Моисей, на глазах у фараона, бросит эту золу к небу,","9":"чтоб она развеялась над всем Египтом. И тогда по всему Египту и у людей, и у скота на коже появятся гнойные нарывы».","10":"Моисей и Аарон набрали по пригоршне золы из печи и предстали перед фараоном. Бросил Моисей золу к небу – и тут же и у людей, и у скота появились на коже гнойные нарывы.","11":"Маги больше не могли состязаться с Моисеем: они сами покрылись нарывами, как и все египтяне.","12":"Но Господь заставил фараона упорствовать, и тот все не слушался (как и предсказывал Моисею Господь).","13":"Господь велел Моисею: «Завтра, рано утром, вновь предстань пред фараоном и скажи ему: „Господь, Бог евреев, говорит: отпусти Мой народ – совершить служение Мне!","14":"На этот раз Я покараю тебя, и твоих вельмож, и весь твой народ самыми страшными карами, чтобы ты понял, что нет на земле никого, Мне подобного!","15":"Если бы Я простер Свою руку и поразил тебя и твой народ чумой, вы исчезли бы с лица земли!","16":"Но Я оставляю тебя в живых – чтобы явить тебе Свою мощь, чтобы прославить Свое имя по всей земле!","17":"Ты все еще превозносишься над Моим народом, не хочешь его отпустить?","18":"Завтра, в этот же час, Я обрушу на Египет такой страшный град, какого не бывало с тех пор, как стоит Египет!","19":"Уведи свои стада под кров, укрой все, что находится под открытым небом. А те люди и скот, что останутся под открытым небом и не спрячутся под кров, будут насмерть побиты градом\"».","20":"Те из фараоновых вельмож, кто испугался слов Господа, спрятали своих рабов и скот под кров.","21":"А те, кто не обратил внимания на слова Господа, оставили и рабов и скот под открытым небом.","22":"Господь велел Моисею: «Воздень руку к небу – и на землю египетскую обрушится град. Он побьет по всему Египту и людей, и скот, и траву».","23":"Простер Моисей посох к небу – и Господь послал на землю гром, и град, и молнии. На всю страну египетскую Господь обрушил град.","24":"Падал град, молнии сверкали – такого сильного града еще не видал народ египетский!","25":"По всему Египту град побил все, что было под открытым небом, – и людей, и скот, и траву – и даже деревья поломал.","26":"Только в земле Тошен не было града – там жили сыны Израилевы.","27":"Фараон позвал Моисея и Аарона и сказал им: «Я виноват! Господь прав, а я и мой народ – мы неправы!","28":"Попросите Господа: довольно уже этого страшного грома и града! Я вас отпускаю, идите!»","29":"Моисей ответил ему: «Когда я выйду из города, я воздену руки к Господу – и тут же гром стихнет и град прекратится. Это чтобы ты знал, что хозяин земли – Господь!","30":"Но я вижу, что и ты, и твои вельможи – вы все еще не боитесь Господа Бога!»","31":"(Лен и ячмень были побиты градом, потому что ячмень уже колосился, а лен цвел.","32":"Но пшеница и полба не пострадали – это поздние злаки.)","33":"Оставил Моисей фараона, вышел из города, воздел руки к Господу – тут же гром и град прекратились и перестал лить дождь.","34":"Но едва фараон увидел, что дождь, град и гром прекратились, он вновь принялся за свое – снова стал упрямиться, вместе со своими вельможами.","35":"По – прежнему упорствовал фараон: не отпустил он сынов Израилевых (как и предсказывал Господь через Моисея)."},"10":{"1":"Господь велел Моисею: «Иди к фараону. Я сделал так, что фараон и его вельможи по – прежнему упорствуют, – это для того, чтобы Я мог показать на них Мои чудеса!","2":"Это чтобы вы рассказывали сыновьям и внукам, как Я восторжествовал над Египтом, как явил Я здесь Свои чудеса! Это чтобы вы знали, кто такой Господь!»","3":"Моисей и Аарон пришли к фараону и сказали ему: «Господь, Бог евреев, говорит: сколько еще ты будешь Мне противиться? Отпусти Мой народ – совершить служение Мне!","4":"А если не отпустишь, завтра Я нашлю на твои владения саранчу! Юна покроет все, так что и земли не будет видно, поест всю зелень, уцелевшую после града, объест все деревья в поле!","6":"Саранча наполнит твой дом и дома твоих вельмож, дома всех египтян. Ни отцы ваши, ни деды такого не видали, с тех пор как вы живете на этой земле!» Повернулся Моисей и вышел от фараона.","7":"Тогда вельможи сказали фараону: «Долго ли нам еще страдать от этого человека? Отпусти их, пусть совершат служение своему богу Господу. Разве ты не видишь, что Египет погибает?»","8":"Моисею и Аарону велели вернуться. Фараон сказал им: «Идите, совершите служение своему богу Господу. Кто из вас пойдет?»","9":"Моисей ответил: «Мы пойдем все, молодые и старые, с сыновьями и дочерьми, с овцами, козами и коровами, – ведь это у нас праздник Господень!»","10":"Но фараон засмеялся: «Чтоб Господь вас так же защищал, как я отпущу вас вместе с вашими детьми! Смотрите, как бы вам в беду не попасть!","11":"Пусть одни мужчины пойдут и совершат служение Господу – как вы и просили». И Моисея с Аароном прогнали прочь.","12":"Господь велел Моисею: «Занеси руку над землей египетской – и придет саранча, и поест все растения, уцелевшие после града».","13":"Моисей простер посох над землей египетской – и Господь послал на Египет восточный ветер. Ветер дул весь день и всю ночь, а наутро принес с востока саранчу.","14":"Пришла саранча на землю египетскую и заполнила всю страну. Саранчи было столько, сколько прежде никогда не бывало, и после не будет.","15":"Всю землю она покрыла – черной стала земля! Саранча поела всю траву и все плоды на деревьях – все, что уцелело после града. Не осталось по всей земле египетской ни зеленой травы, ни листьев на деревьях.","16":"Фараон спешно позвал Моисея и Аарона и сказал им: «Виноват я перед вашим богом Господом и перед вами.","17":"Но простите меня и на этот раз: попросите своего бога Господа убрать от нас эту пагубу!»","18":"Моисей вышел от фараона, попросил Господа –","19":"и Господь послал с запада очень сильный ветер, который унес саранчу и утопил ее в Чермном море. Не осталось саранчи в пределах египетских.","20":"Но Господь сделал так, что фараон продолжал упорствовать: не отпустил он сынов Израилевых.","21":"Господь велел Моисею: «Воздень руку к небу – и тьма настанет по всей земле египетской, пусть ходят во тьме на ощупь!»","22":"Простер Моисей руку к небу – и на три дня по всей земле египетской настали тьма и мрак.","23":"Не видели люди друг друга, три дня с места двинуться не могли. Светло было лишь там, где жили сыны Израилевы.","24":"Фараон позвал Моисея и сказал: «Идите, совершите служение Господу. Но скот ваш, и мелкий и крупный, пусть останется. А дети пусть идут с вами».","25":"Моисей ответил: «Ты должен отпустить с нами скот, чтобы мы принесли нашему Богу, Господу, жертвы всесожжения и пиршественные жертвы.","26":"Весь наш скот, до единого животного, должен пойти с нами, и уже там, на месте, мы отберем, что принести в жертву нашему Богу, Господу. Ведь пока мы туда не придем, мы не узнаем, каких животных принести Господу в жертву».","27":"Но Господь сделал так, что фараон упорствовал по – прежнему: не хотел он их отпускать.","28":"«Уходи, – сказал фараон Моисею. – И впредь ко мне не являйся. Явишься – умрешь».","29":"Моисей ответил: «Как ты сказал, так и будет. Больше я тебя не увижу»."},"11":{"1":"Господь сказал Моисею: «Новую беду обрушу Я на фараона и на Египет. Вот тогда фараон вас отпустит, и не просто отпустит, а выгонит.","2":"А ты вели сынам и дочерям Израилевым, чтобы они просили у своих соседей и соседок серебряные и золотые вещи».","3":"(Господь сделал так, что египтяне были добры к сынам Израилевым. К тому же все египтяне – и вельможи фараона и простой народ – чтили Моисея.)","4":"Моисей сказал: «Господь говорит: „В полночь Я пройду по Египту,","5":"и умрут все первенцы в этой стране – и первенец фараона, восседающего на престоле, и первенец рабыни, которая мелет муку ручными жерновами, и все первенцы скота.","6":"По всему Египту будет стоять такой стон, какого никогда еще никто не слышал и не услышит впредь.","7":"Но на сынов Израилевых и на их скот даже собака залаять не посмеет! Вы увидите: с сынами Израилевыми Господь не сделает того, что сделает с египтянами\"».","8":"«Твои вельможи, – сказал Моисей фараону, – придут ко мне, падут ниц и станут умолять, чтобы я ушел от вас, вместе с моим народом. И тогда мы от вас уйдем». И Моисей, разгневанный, вышел от фараона.","9":"Господь сказал Моисею: «Фараон вас не слушает: это нужно, чтобы еще больше Моих чудес было явлено в Египте».","10":"Моисей и Аарон сотворили перед фараоном множество чудес! Но Господь сделал так, что фараон упорствовал и не отпускал сынов Израилевых из Египта."},"12":{"1":"Там, в Египте, Господь сказал Моисею и Аарону:","2":"«Этот месяц для вас должен быть первым из месяцев – первым месяцем года.","3":"Скажите общине Израиля, что в десятый день этого месяца каждая семья должна взять из стада по ягненку.","4":"Если семья так мала, что не съест целого ягненка, то пусть возьмут вместе с ближайшими соседями одного ягненка на всех, рассчитав нужное число людей – исходя из того, кто сколько съест.","5":"Ягненок должен быть без телесного изъяна, годовалый, мужского пола; вместо ягненка можно взять козленка.","6":"Дождитесь четырнадцатого дня этого месяца и с наступлением сумерек зарежьте ягненка: так должны сделать все, кто принадлежит к общине Израиля.","7":"Пусть возьмут его кровь и помажут ею оба дверных косяка и притолоку в тех домах, где будут его есть.","8":"Мясо должно быть съедено в ту же ночь; есть его нужно поджаренным на огне, с пресным хлебом и горькими травами.","9":"Не ешьте это мясо сырым или вареным: ягненок должен быть зажарен на огне – с головой, ногами и потрохами.","10":"Ничего не оставляйте до утра: что не съедите к утру, то сожгите.","11":"Ешьте его так: подпоясавшись и обувшись, с посохами в руках. С поспешностью ешьте его; это Пасха Господня.","12":"В эту ночь Я пройду по Египту и убью всех первенцев в этой стране, и первенцев людей и первенцев скота. Это будет Мой суд над всеми богами Египта. Я – Господь!","13":"Но ваши дома будут помечены кровью, и Я, увидев кровь, пройду мимо. Я поражу Египет, но вас минует удар Смерти.","14":"Этот день должен быть для вас днем памяти: празднуйте его как праздник Господа. Празднуйте его из рода в род – это вам предписание навеки.","15":"Семь дней вы должны есть пресный хлеб. В первый же из этих дней удалите закваску из своих домов. Всякий, кто в эти семь дней станет есть дрожжевой хлеб, будет отторгнут от народа Израилева.","16":"Первый из этих дней должен быть провозглашен святым – и седьмой день пусть будет провозглашен святым. В эти дни вы не должны выполнять никакой работы, кроме приготовления пищи – только такую работу можно делать в эти дни.","17":"Справляйте праздник Пресных Хлебов: в этот день Я вывел ваше воинство из Египта. Отмечайте этот день из рода в род – это вам предписание навеки.","18":"В первый месяц, с вечера четырнадцатого числа до вечера двадцать первого, вы должны есть только пресный хлеб.","19":"Семь дней в ваших домах не должно быть закваски. Всякий, кто ест в эти дни дрожжевой хлеб, – будь то переселенец или уроженец вашей страны – тот будет отторгнут от общины Израиля.","20":"Где бы вы ни жили, не ешьте в эти дни дрожжевого хлеба – ешьте пресный хлеб».","21":"Моисей созвал всех старейшин Израиля и сказал им: «Пусть каждая семья выберет себе ягненка и заколет его – приготовит Пасху.","22":"Потом возьмите пучок иссопа, обмакните в чан со слитой кровью и помажьте этой кровью притолоку и оба дверных косяка. И пусть никто из вас до утра не выходит из дому.","23":"Пойдет Господь убивать египтян, увидит кровь на притолоке и косяках – и пройдет Господь мимо этой двери, не даст Смерти войти в ваш дом и убить вас.","24":"Соблюдайте это предписание вовек, вы и ваши потомки.","25":"Когда вы придете в ту землю, которую Господь даст вам, как обещал, совершайте там этот обряд.","26":"Если спросят ваши дети: „Что за обряд вы совершаете?\" –","27":"отвечайте им так: „Это пасхальная жертва Господу. Когда Господь убивал египтян, Он миновал дома сынов Израилевых и пощадил наши семьи\"». И весь народ склонился и пал ниц пред Господом.","28":"Затем сыны Израилевы пошли и сделали все в точности так, как Господь повелел Моисею и Аарону.","29":"А в полночь Господь убил всех первенцев в Египте: умерли и первенец фараона, восседающего на престоле, и первенец пленника, сидящего в темнице, и все первенцы скота.","30":"Встал в ту ночь фараон, встали его вельможи и все египтяне – и великий стон поднялся по всему Египту: в каждой семье был умерший.","31":"В ту же ночь фараон позвал Моисея и Аарона и сказал им: «Уходите от нас прочь, вместе со всеми сынами Израилевыми! Идите, совершите служение Господу, как вы просили.","32":"Забирайте с собой свой скот, крупный и мелкий, как вы просили. Уходите и благословите меня!»","33":"Египтяне торопили сынов Израилевых, чтобы те скорее покинули их страну. «Иначе, – думали египтяне, – мы все умрем!»","34":"И пришлось сынам Израилевым уносить еще не заквашенное тесто – каждый завернул свою квашню в плащ и понес на плече.","35":"Сыны Израилевы выполнили наказ Моисея – просили у египтян серебряные и золотые вещи и одежду.","36":"А Господь сделал так, что египтяне были добры к сынам Израилевым и отдавали им все, чего бы те ни попросили. Так сыны Израилевы ушли из Египта с богатой добычей!","37":"Из Раамсеса сыны Израилевы пошли к Суккоту – около шестисот тысяч пеших мужчин, не считая женщин и детей.","38":"С ними шло много иноплеменников, шли огромные стада овец, коз и коров.","39":"Из теста, которое они унесли из Египта в своих квашнях, сыны Израилевы испекли пресные лепешки. Тесто даже не успело закваситься: их гнали прочь из Египта, они не могли задерживаться и не успели приготовить себе еды на дорогу.","40":"Сыны Израилевы жили в Египте четыреста тридцать лет.","41":"В день, когда четыреста тридцать лет истекли, вышло из Египта воинство Господне.","42":"Та ночь была у Господа ночью бдения: Он уводил из Египта сынов Израилевых. Это ночь Господня! Из рода в род это ночь бдения у сынов Израилевых.","43":"Господь сказал Моисею и Аарону: «Вот предписания о Пасхе. Чужеземец не должен есть Пасху.","44":"Раб, купленный тобой, может есть Пасху после того, как ты сделаешь ему обрезание.","45":"Живущий у тебя наемный работник не должен есть Пасху.","46":"Ягненка надо есть в доме – не выноси его мяса из дому. Костей его не ломайте.","47":"Вся община Израиля должна совершать Пасху.","48":"Если живущий у вас переселенец пожелает совершить Пасху Господню, то всем мужчинам в его семье надо сделать обрезание, а после этого пусть приходит и совершает Пасху: он будет как уроженец вашей страны. Но ни один необрезанный не должен есть Пасху.","49":"Одно правило – и для уроженцев вашей страны, и для живущих у вас переселенцев».","50":"Сыны Израилевы сделали все в точности так, как повелел Господь Моисею и Аарону.","51":"В тот самый день Господь вывел из Египта воинство сынов Израилевых."},"13":{"1":"Господь сказал Моисею:","2":"«Посвящайте Мне всех первенцев, какие родятся у сынов Израилевых, – первый плод материнского чрева – и первенцев людей, и первенцев скота. Они принадлежат Мне».","3":"Моисей сказал народу: «Помните этот день, в который могучая рука Господа вывела вас из Египта, из неволи. Не ешьте в этот день дрожжевого хлеба.","4":"Вы уходите сегодня, в месяце авиве.","5":"Когда Господь приведет тебя в землю ханаанеев, хеттов, амореев, хиввеев и евусеев – ибо Он поклялся твоим отцам, что отдаст тебе эту землю, источающую молоко и мед, – тогда ты должен будешь совершать в этом месяце такой обряд:","6":"семь дней есть только пресный хлеб, а на седьмой день праздновать праздник Господень.","7":"Семь дней ешьте пресный хлеб: нигде в вашей земле не должно быть ни дрожжевого хлеба, ни закваски.","8":"В тот день ты скажешь своему сыну: „Это в память о том, что сделал для меня Господь, когда я уходил из Египта\".","9":"Это должно быть для тебя как знак на руке, как знак памяти на челе – и пусть Закон Господень всегда будет у тебя на устах, ибо Господь Своей могучей рукой вывел тебя из Египта.","10":"Выполняйте это предписание из года в год, в назначенное время.","11":"Когда Господь приведет тебя в землю ханаанеев – ибо Он поклялся тебе и твоим отцам, что отдаст тебе эту землю, –","12":"тогда ты должен будешь отдавать Ему всех первенцев. Все первенцы твоего скота, если они мужского пола, принадлежат Господу.","13":"За первенца ослицы отдавай выкуп – ягненка, а если не хочешь выкупить осленка – сломай ему шею. И за первенцев человека – за своих первенцев – отдавай выкуп.","14":"Когда в будущем спросит у тебя сын: „Что это значит?\" – отвечай ему так: „Господь могучей рукою вывел нас из египетской неволи.","15":"Когда фараон упорствовал и не отпускал нас, то Господь убил всех первенцев в Египте, и у людей и у скота. Вот почему всех первенцев мужского пола я приношу в жертву Господу, а за своих первенцев отдаю выкуп.","16":"Это должно быть для тебя как знак на руке, как повязка на челе, ибо Господь Своей могучей рукой вывел нас из Египта\"».","17":"Когда фараон отпустил сынов Израилевых, Бог не повел их через филистимскую землю – это слишком короткий путь. Бог думал: когда сыны Израилевы увидят, что им предстоит война, они могут передумать и вернуться в Египет.","18":"И Бог повел их кружным путем, по пустыне, мимо Чермного моря. Походным строем шли сыны Израилевы, покидая Египет.","19":"Моисей унес из Египта останки Иосифа – ведь Иосиф взял с сынов Израилевых клятву, что когда Бог о них вспомнит, они унесут из Египта его останки.","20":"Покинув Суккот, сыны Израилевы остановились в Этаме, что на краю пустыни.","21":"Господь Сам шел перед ними: днем – как столп облачный, указывая путь, а ночью – как столп огненный, освещая дорогу, чтобы они могли идти и днем и ночью.","22":"И днем столп облачный не покидал, и ночью столп огненный не покидал народа Израилева."},"14":{"1":"Господь велел Моисею:","2":"«Скажи сынам Израилевым, чтобы они повернули назад и остановились у Пи – Хахирота, между Мигдолом и морем, близ Баал – Цефона. Разбейте там стан у берега моря.","3":"Пусть фараон думает, что сыны Израилевы заблудились, что пустыня преграждает им путь.","4":"Я сделаю так, что он, упорствуя, погонится за вами, – и вот тогда Я восторжествую над фараоном и его войском! Узнают египтяне, кто такой Господь!» Сыны Израилевы сделали, как повелел им Господь.","5":"Царю египетскому сообщили, что народ Израилев ушел. Тогда фараон и его вельможи вдруг передумали. «Что мы наделали?! – сказали они. – Мы отпустили сынов Израилевых, наших работников!»","6":"Фараон велел приготовить свою колесницу и собрал свое войско.","7":"Он взял с собою шестьсот отборных колесниц, все колесничное войско египетское. На каждой колеснице стояли опытные воины.","8":"И Господь сделал так, что фараон, царь египетский, упорствуя, погнался за сынами Израилевыми. А сыны Израилевы шли ничего не опасаясь.","9":"Египтяне пустились за ними в погоню – все конные колесницы фараона, все его всадники, все его войско – и настигли их на стоянке у моря, при Пи – Хахироте, близ Баал – Цефона.","10":"Фараон приближался. Посмотрели сыны Израилевы – и видят: египтяне гонятся за ними! В страхе они стали взывать к Господу.","11":"«Что, в Египте негде было похоронить нас? – кричали они Моисею. – Ты привел нас сюда, в пустыню, чтобы мы здесь погибли? Что ты наделал, зачем увел нас из Египта?","12":"Говорили мы тебе в Египте: „Оставь нас, пусть мы будем рабами египтян!\" Уж лучше быть рабами египтян, чем погибнуть в пустыне!» –","13":"«Не бойтесь! – ответил Моисей народу. – Стойте, и смотрите, как Господь вас спасет. В последний раз вы видите перед собой этих египтян – больше вы их никогда не увидите!","14":"За вас будет воевать Сам Господь! Успокойтесь».","15":"И Господь сказал Моисею: «Что ты взываешь ко Мне? Вели сынам Израилевым идти вперед!","16":"А сам протяни посох, простри его над морем – и море расступится, и сыны Израилевы пойдут по дну моря, как по суше.","17":"Я сделаю так, что египтяне, упорствуя, устремятся за вами следом, – и вот тогда Я восторжествую над фараоном и его войском, над его колесницами и всадниками!","18":"Узнают египтяне, кто такой Господь, – когда Я восторжествую над фараоном, над его колесницами и всадниками!»","19":"Ангел Божий, что шел перед строем израильтян, встал позади строя. Облачный столп, что был перед ними, встал позади.","20":"Он разделил строй египтян и строй израильтян. Он был как темное облако – а ночью светился. И в ту ночь два строя не сходились друг с другом.","21":"А Моисей простер руку над морем, и всю ночь Господь гнал воды моря сильным восточным ветром. Он обратил море в сушу, воды расступились,","22":"и пошли сыны Израилевы по дну моря, как по суше. По правую руку от них стояла стена воды и по левую стояла стена воды.","23":"Тогда египтяне – все конные колесницы фараона, все его всадники, – погнались за сынами Израилевыми по дну моря.","24":"На рассвете взглянул Господь на египетское войско из столпа огненного и облачного – в ужас и смятение привел их.","25":"Он сделал так, что у их колесниц колеса слетали с осей; египтяне с трудом их тащили. «Надо нам бежать прочь от сынов Израилевых! – сказали египтяне. – За них Господь: Он Сам воюет с Египтом».","26":"И Господь сказал Моисею: «Протяни руку над морем – воды вернутся и потопят египтян, и колесницы, и всадников!»","27":"Простер Моисей руку над морем – и к утру море вернулось. Прямо навстречу его водам бежали египтяне – и вверг Господь египтян в бездну морскую!","28":"Вернулась вода и поглотила их всех – и колесницы, и всадников, и все войско фараоново, что погналось по дну моря за сынами Израилевыми. Ни один египтянин не уцелел!","29":"А сыны Израилевы прошли по дну моря, как по суше; по правую руку от них стояла стена воды, и по левую – стена воды.","30":"Так спас Господь в тот день сынов Израилевых от египтян. Увидели сыны Израилевы трупы египтян на морском берегу,","31":"увидели, что сделала с египтянами могучая рука Господа, – и страх пред Господом объял народ Израилев, и поверили они Господу и Моисею, рабу Его."},"15":{"1":"Тогда Моисей и сыны Израилевы запели песнь Господу: Воспою Господу: Он велик! Он коня и всадника в море вверг!","2":"Господь – моя мощь, Он – сила моя! Он – спасенье мое! Он мой Бог, я прославлю Его! Бог отцов моих – возвеличу Его!","3":"Господь – воин! Имя Его – Господь!","4":"Колесницы фараона, войска его в море Он вверг, его лучших воинов в море Чермном потопил.","5":"Поглотила пучина их: они камнем пошли на дно!","6":"Господь! Твоя рука крепка и сильна! Господь! Твоя рука сразила врага!","7":"Велик Ты! Недругов Ты поверг! Как огонь – солому, Твой гнев их сжег!","8":"Дунул Ты – и вздыбились воды, волны встали стеной, твердью стала пучина!","9":"«Догоню, настигну, – подумал враг, – поживлюсь добычей: возьму, что хочу! Меч обнажу – уничтожу всех!»","10":"Но Ты дунул – и море покрыло их: как свинец, под воду они ушли.","11":"Нет подобных Тебе средь богов, Господь! Нет, Могучий, подобных Тебе средь Святых! Страшный в славе! Творец чудес!","12":"Простер руку – земля поглотила врагов!","13":"А народ, что Тобою спасен, Ты повел, защищая, любя, в Свой святой край повел,","14":"и народы, услышав, трепещут! Дрожат жители Филистии,","15":"в ужас пришли вожди Эдома, страхом объяты владыки Моава, жутко жителям Ханаана.","16":"Пусть же охватит их страх и ужас! Под рукой Твоей тяжкой пусть станут как камень, пока мимо них идет Твой народ – народ, который Ты сделал Своим!","17":"Ты поселишь его на Твоей горе, там, Господь, Ты жилище построил Себе, там, Владыка, святилище Ты воздвиг!","18":"Воцарится Господь – навеки!","19":"Когда вошли вглубь моря конные колесницы фараона и его всадники, то Господь повернул против них воды морские. А сыны Израилевы прошли по дну моря, как по суше!","20":"Мирьям – пророчица, сестра Аарона, взяла бубен, и все женщины пошли за ней следом – с плясками, с бубнами.","21":"И Мирьям запела: «Пойте Господу: Он велик! Он коня и всадника в море вверг!»","22":"От Чермного моря Моисей повел сынов Израилевых в пустыню Шур. Три дня они шли по пустыне и нигде не могли найти воды.","23":"А когда пришли в Мару , то не могли пить там воду – вода была горькой. (Потому это место и называется Мара.)","24":"Люди стали роптать на Моисея. «Что мы будем пить?» – спрашивали они.","25":"Моисей воззвал к Господу, и Господь указал ему дерево. Моисей бросил кусок этого дерева в воду, и вода стала пригодной для питья. Там Он дал им законы и правила, там Он их подверг испытанию.","26":"Господь сказал: «Если вы будете слушаться Господа, вашего Бога, и делать то, что Ему угодно, внимать Его повелениям и соблюдать Его законы, то Я никогда не поражу вас теми болезнями, какие послал на египтян. Я Господь – ваш Целитель!»","27":"Сыны Израилевы пришли в Элим. Там было двенадцать источников и семьдесят финиковых пальм. Там, у источников, они сделали остановку."},"16":{"1":"Покинув Элим, община сынов Израилевых пришла в пустыню Син, что лежит между Элимом и Синаем. Это было на второй месяц после их ухода из Египта, в пятнадцатый день месяца.","2":"Там, в пустыне, община сынов Израилевых вновь принялась роптать на Моисея и Аарона.","3":"«Лучше бы нам было умереть в Египте от руки Господа, – говорили сыны Израилевы. – Там мы сидели вокруг котлов с мясом, у нас было вдоволь хлеба. А вы привели нас в эту пустыню, чтобы уморить весь народ голодом!»","4":"И Господь сказал Моисею: «Я пошлю вам хлеб с неба, как дождь. Каждый день люди будут выходить и собирать себе еду на день, а Я испытаю их, как они соблюдают Закон Мой.","5":"Когда же наступит шестой день недели и они станут готовить собранное в этот день, то окажется, что они собрали вдвое больше обычного».","6":"Моисей и Аарон сказали сынам Израилевым: «Вечер настанет, и вы поймете: это Господь вас увел из Египта.","7":"Утро настанет, и вы увидите Славу Господню. Ибо Господь услышал, как вы на Него ропщете. А мы кто такие? Что нас упрекать?»","8":"Моисей сказал: «Вечером Господь ниспошлет вам мясо, а утром – вдоволь хлеба. Он услышал, как вы ропщете на Него. А мы кто такие? Не нас вы упрекаете, а Господа!»","9":"Моисей сказал Аарону: «Вели общине сынов Израилевых предстать пред Господом, ибо Господь услышал их ропот».","10":"Когда Аарон передал эти слова общине сынов Израилевых, они повернулись в сторону пустыни – и там, в облаке, им явилась Слава Господня.","11":"Господь сказал Моисею:","12":"«Я услышал ропот сынов Израилевых. Скажи им так: вечером будете есть мясо, а утром у вас будет вдоволь хлеба. И тогда вы поймете, что Я, Господь, – Бог ваш».","13":"И вот, вечером прилетели перепела – весь стан был ими полон. А утром вокруг стана выпала роса.","14":"Когда роса испарилась, стало видно, что вся пустыня покрыта чем – то тонким и хрустящим – тонким, как иней.","15":"Сыны Израилевы увидели – и, не понимая, что это такое, стали спрашивать друг друга: «Что это?» Моисей сказал им: «Это хлеб, который вам посылает Господь.","16":"Вот что повелел Господь: „Пусть каждый соберет, сколько нужно на его семью, – по одному омеру на каждого человека в шатре\"».","17":"Так и сделали сыны Израилевы. Кто – то собрал больше, кто – то меньше,","18":"но когда собранное мерили омером, то оказывалось, что у тех, кто собрал больше, нет никакого излишка, а у тех, кто собрал меньше, нет недостачи: у каждого было столько, сколько нужно его семье.","19":"«Ничего из этого на завтра не откладывайте», – велел Моисей.","20":"Но его не послушали: отложили до утра часть собранного, и отложенное испортилось, в нем завелись черви. Моисей разгневался на этих людей.","21":"Всякое утро каждый собирал, сколько нужно его семье. А днем все несобранное таяло на солнце.","22":"В шестой день недели они собрали вдвое больше – по два омера на человека. Когда вожди общины пришли и сказали об этом Моисею,","23":"он ответил: «Господь говорил об этом. Завтра день покоя, святая суббота Господня. Испеките, что хотите испечь, сварите, что хотите сварить, и что не съедите, то отложите на завтра».","24":"Люди, как и велел Моисей, отложили, что не съели, до следующего дня. На этот раз отложенное не испортилось, червей в нем не было.","25":"Моисей сказал: «Сегодня ешьте это. Сегодня суббота Господня, и на земле вы ничего не найдете.","26":"Шесть дней собирайте, а седьмой день – суббота, в этот день вам ничего не найти».","27":"Некоторые и в седьмой день недели пошли собирать, но ничего не нашли.","28":"Господь сказал Моисею: «До каких пор вы будете нарушать повеления и правила, данные Мною?","29":"Смотрите: Господь дал вам субботу, и потому в шестой день недели Он посылает вам пищу на два дня. А в седьмой день каждый должен оставаться у себя и никуда не выходить».","30":"И в седьмой день недели народ пребывал в покое.","31":"Израильтяне назвали эту пищу манной. Манна была белая, похожа на кориандровое семя, а по вкусу напоминала медовые лепешки.","32":"Моисей сказал: «Вот что повелел Господь: пусть один омер манны хранится у вас из рода в род, чтобы всякий мог видеть хлеб, которым Господь вас кормил в пустыне, когда вывел вас из Египта.","33":"Возьми кувшин, – сказал Моисей Аарону, – положи в него омер манны и поставь пред Господом, чтобы хранился у вас из рода в род».","34":"И Аарон сделал так, как Господь повелел Моисею: он поставил кувшин с манной храниться рядом с Заветом.","35":"Сыны Израилевы питались манной сорок лет – пока не пришли в обитаемую землю. Они питались манной, пока не достигли рубежей земли ханаанской.","36":"(Омер – это десятая часть эфы .)"},"17":{"1":"Покинув пустыню Син, община сынов Израилевых шла небольшими переходами, следуя указаниям Господа. Они остановились в Рефидиме. Там не было воды – нечего было пить.","2":"Люди стали обвинять Моисея. «Дай нам воды! – требовали они. – Мы хотим пить». – «Зачем вы обвиняете меня? – сказал Моисей. – Зачем вы Господа испытываете?»","3":"Но люди страдали от жажды и упрекали Моисея: «Зачем ты увел нас из Египта? Чтоб уморить нас жаждой, вместе с детьми и скотом?»","4":"Моисей воззвал к Господу: «Что мне делать с этим народом? Они вот – вот побьют меня камнями!»","5":"И Господь велел Моисею: «Выйди вперед, встань перед народом, и возьми с собой нескольких из старейшин Израиля. Возьми посох, которым ты ударил по водам Нила, и иди.","6":"Там, на Хориве, Я стану перед тобою на скале. Ты ударишь по скале, и из нее потечет вода, пусть народ пьет». Так и сделал Моисей, на глазах у старейшин Израиля.","7":"А место это было названо Масса и Мерива, потому что там сыны Израилевы упрекали и испытывали Господа, говоря: «Так с нами Господь или нет?»","8":"Амалекитяне пришли в Рефидим и напали на сынов Израилевых.","9":"Моисей сказал Иисусу: «Отбери людей, с которыми ты пойдешь на амалекитян. А я завтра, с посохом Божьим в руке, стану на вершине холма».","10":"Иисус выполнил приказ Моисея и вступил в сражение с амалекитянами, а Моисей, вместе с Аароном и Ором, стал на вершине холма.","11":"Когда Моисей поднимал руку – одолевал Израиль, а когда опускал – Амалек.","12":"Но руки Моисея отяжелели. Тогда принесли камень и Моисей сел на него, а Ор и Аарон стали с двух сторон поддерживать его руки. Пока не зашло солнце, руки Моисея были воздеты –","13":"и Иисус одолел Амалека, перебил его людей мечом.","14":"Господь сказал Моисею: «Запиши в книге, чтоб не было забыто, и возвести Иисусу: Я сотру Амалека с лица земли – и имени его не останется!»","15":"Моисей воздвиг жертвенник и назвал его Яхве–Нисси ,","16":"и сказал: «Это значит: Господне знамя в руке! Война Господа с Амалеком – из рода в род!»"},"18":{"1":"Мидьянский жрец Итро, тесть Моисея, услышал про то, что сделал Бог для Моисея и для Своего народа, Израиля, – про то, что Господь вывел народ Израилев из Египта.","2":"Вместе с Итро находились Циппора, жена Моисея (которую Моисей перед этим отослал обратно к отцу),","3":"и оба его сына (одного звали Гершом, что значит: «Я поселился на чужбине», –","4":"а другого Элиэзер, что значит: «Бог отца моего пришел мне на помощь и спас от меча фараонова»).","5":"Итро привел их к Моисею – в пустыню, к горе Божьей, где стоял стан Моисея, –","6":"и велел передать ему: «Пришел Итро, твой тесть, с твоей женой и сыновьями».","7":"Моисей вышел, поклонился тестю, поцеловал его – и, обменявшись приветствиями, они вошли в шатер.","8":"Моисей рассказал тестю о том, что сделал Господь с фараоном и египтянами, заступаясь за сынов Израилевых, и о том, как труден был их путь через пустыню и как Господь их спасал.","9":"Порадовался Итро, что так много добра сотворил Господь для сынов Израилевых, спасая их от египтян.","10":"И сказал Итро: «Благословен Господь, который спас вас от египтян и фараона, избавил ваш народ от египтян!","11":"Теперь я знаю, что Господь превыше всех богов, как бы они не превозносились!»","12":"Итро, тесть Моисея, принес Богу пиршественные жертвы и жертву всесожжения. Пришел Аарон, пришли старейшины Израиля – и была у них с тестем Моисея совместная трапеза пред лицом Божьим.","13":"На следующий день Моисей разбирал тяжбы между израильтянами. С утра до вечера он был окружен людьми.","14":"Увидев это, тесть спросил его: «Что ты делаешь здесь, с этими людьми? Почему ты перед ними сидишь, один, а они все стоят вокруг тебя, с утра до вечера?» –","15":"«Они приходят ко мне, чтобы вопрошать Бога, – отвечал Моисей. –","16":"Когда нужно решить какое – нибудь дело, они идут ко мне, а я разбираю их тяжбы и учу их законам и правилам Божьим». –","17":"«Неправильно ты делаешь, – сказал ему тесть. –","18":"И сам измучишься, и эти люди измучатся. Тяжело тебе, один ты не справишься.","19":"Послушай моего совета, и да пребудет с тобою Бог! Будь посредником между этим народом и Богом, передавай их дела на рассмотрение Бога,","20":"разъясняй им законы и правила, учи, по какому пути им идти и как поступать.","21":"А из народа выбери достойных людей – богобоязненных, правдивых, неподкупных – и поставь начальниками: кого над тысячей человек, кого над сотней, кого над полусотней, кого над десятком.","22":"Они постоянно будут с народом, разбирая тяжбы между людьми, и все важные дела будут передавать тебе, а незначительные – решать сами. Твое бремя станет легче: они разделят его с тобою.","23":"Если сделаешь так, Бог будет давать тебе указания, а ты и сам сможешь выдержать, и люди будут с миром возвращаться к себе».","24":"Моисей послушался тестя и сделал, как тот сказал:","25":"выбрал из народа Израилева достойных людей и поставил их начальниками – кого над тысячей человек, кого над сотней, кого над полусотней, кого над десятком.","26":"Они постоянно были с народом, разбирали тяжбы между людьми и все трудные дела передавали Моисею, а незначительные решали сами.","27":"Моисей простился с тестем, и тот отправился домой, в свою землю."},"19":{"1":"В новолуние третьего месяца после ухода сынов Израилевых из Египта они достигли Синайской пустыни.","2":"Покинув Рефидим, сыны Израилевы пришли в Синайскую пустыню, остановились и стали лагерем у горы.","3":"Моисей взошел к Богу. И воззвал к нему Господь с горы: «Скажи племени Иакова, возвести сынам Израилевым:","4":"„Вы видели, что Я сделал с египтянами, видели, как нес Я вас на орлиных крыльях и принес к Себе!","5":"Если вы будете Мне послушны и верны договору со Мною, то вы будете Моим драгоценным сокровищем среди всех народов земли! Вся земля Моя,","6":"а вы будете у Меня царством священников, святым народом!\" Передай эти слова сынам Израилевым».","7":"Моисей вернулся, созвал старейшин и передал им эти слова, как повелел ему Господь.","8":"Весь народ, как один человек, ответил: «Мы будем следовать словам Господа». Моисей сообщил Господу ответ народа.","9":"Господь сказал Моисею: «Я приду к тебе в густом облаке, чтобы народ услышал, как Я с тобой говорю, и впредь всегда верил тебе». Когда Моисей сообщил Господу ответ народа,","10":"Господь сказал Моисею: «Иди к народу; освяти их за сегодняшний и за завтрашний день, пусть они выстирают свои одежды","11":"и готовятся к послезавтрашнему дню: в этот день, на глазах у всего народа, Господь сойдет на гору Синай.","12":"Проведи для людей границу вокруг горы и вели на гору не подниматься и до ее подножия не дотрагиваться. Всякий, кто прикоснется к горе, должен быть предан смерти.","13":"Но не притрагивайтесь к нему руками – убейте его камнем или стрелой. Кто бы это ни был – животное или человек – нельзя оставлять их в живых, раз они при звуках рога пытались подняться на гору».","14":"Моисей спустился с горы к народу и освятил народ. Люди выстирали свои одежды,","15":"и Моисей сказал: «Готовьтесь к послезавтрашнему дню. Не прикасайтесь к женщинам».","16":"На третий день с раннего утра ударили громы и молнии, и гору окутало густое облако. Разнесся громкий звук рога, и люди в стане затрепетали.","17":"Моисей повел народ из стана навстречу Богу. Они встали под горой,","18":"а гора Синай была вся окутана дымом, ибо Господь – как огонь – сошел на ее вершину. Гора дымилась, словно печь, и содрогалась.","19":"Звук рога становился все сильнее и сильнее. Моисей говорил, а Бог отвечал ему голосом грома.","20":"Господь сошел на вершину Синая и призвал Моисея к Себе, на вершину, и Моисей поднялся.","21":"Господь сказал Моисею: «Спустись и предупреди людей, чтобы они не смели приближаться к Господу и видеть Его: это многим из них будет стоить жизни.","22":"А священники, собирающиеся приблизиться к Господу, должны освятить себя, или Господь уничтожит их». –","23":"«Народ не будет подниматься на гору Синай, – сказал Моисей Господу. – Ведь Ты предупредил нас, и я провел границу вокруг горы и провозгласил гору священной».","24":"Господь сказал Моисею: «Иди, спустись, и возвращайся сюда с Аароном. А священники и простой народ пусть не смеют подниматься к Господу, – или Господь уничтожит их».","25":"Моисей спустился к народу и возвестил ему это."},"20":{"1":"Вот слова, сказанные Богом:","2":"«Я Господь, твой Бог, который вывел тебя из Египта, из неволи.","3":"Не должно быть у тебя других богов наряду со Мною.","4":"Не делай изваяний – никаких изображений того, что вверху на небе, или того, что внизу на земле, или того, что в воде, ниже земли.","5":"Не поклоняйся им и не служи им, ибо Я, Господь, Бог твой, – ревнивый Бог. За грехи отцов, отвергнувших Меня, Я караю их детей, и внуков, и правнуков.","6":"А для тех, кто Меня любит и исполняет Мои повеления, – Я покровитель их потомков даже в тысячном поколении!","7":"Не произноси попусту имя Господа, Бога твоего. Господь не оставит безнаказанным того, кто произносит Его имя попусту.","8":"«Помни, что суббота – священный день.","9":"Шесть дней работай, выполни все свои дела,","10":"а седьмой день – суббота: он принадлежит Господу, твоему Богу. Работать в этот день нельзя никому – ни тебе, ни сыну твоему, ни дочери, ни рабу твоему, ни рабыне, ни твоему скоту, ни переселенцу, что живет в твоем городе.","11":"Ибо шесть дней Господь творил небо и землю, и море, и все, что их наполняет, а в седьмой день пребывал в покое. Поэтому благословил Господь субботний день и сделал его священным.","12":"Чти отца и мать, чтобы долгой была твоя жизнь на той земле, которую Господь, твой Бог, дарует тебе.","13":"Не убивай.","14":"Не прелюбодействуй.","15":"Не воруй.","16":"Не давай ложных показаний против ближнего.","17":"Не желай чужого дома, не желай чужой жены, чужих рабов и рабынь, чужих быков и ослов – ничего чужого».","18":"Весь народ видел и слышал громы и молнии, и звук рога, и дымящуюся гору. Затрепетали люди, отошли и стали поодаль.","19":"«Говори с нами ты, – сказали они Моисею, – и мы будем тебя слушать. Не надо, чтобы Бог говорил с нами, а то мы умрем». –","20":"«Не бойтесь, – ответил Моисей. – Бог пришел, чтобы вас испытать и чтобы, объятые страхом Божьим, вы впредь не грешили».","21":"Народ стоял в отдалении, а Моисей приблизился к грозовой туче, в которой пребывал Бог.","22":"Господь велел Моисею: «Скажи сынам Израилевым: „Вы видели, что Я обращался к вам с неба.","23":"Не делайте себе серебряных и золотых богов – не ставьте их рядом со Мной!","24":"Воздвигни для Меня земляной жертвенник и приноси на нем жертвы всесожжения и пиршественные жертвы – мелкий и крупный скот из твоих стад. И на всяком месте, где Я провозглашу Свое имя, Я буду приходить к тебе и благословлять тебя.","25":"Если будешь воздвигать для Меня каменный жертвенник, то не употребляй тесаных камней: отесывая камень, ты осквернишь его.","26":"Не восходи на Мой жертвенник по ступеням, чтобы не обнажился над ним твой срам\"»."},"21":{"1":"ВОТ ЗАКОНЫ, КОТОРЫЕ ТЫ ДОЛЖЕН ИМ ДАТЬ:","2":"Если ты купил раба – еврея, пусть он работает на тебя шесть лет, а на седьмой год ты должен отпустить его на свободу без выкупа.","3":"Если он пришел один, пусть уходит один, а если пришел с женой, то вместе с ним пусть уйдет и жена.","4":"Если хозяин дал ему жену и она родила детей, то жена и дети принадлежат хозяину, а раб пусть уходит один.","5":"Если раб скажет: «Я привязан к хозяину, к жене и детям, не хочу на свободу», –","6":"то пусть хозяин подведет его к Богу – пусть подведет его к двери или к дверному косяку – и там проколет ему ухо шилом. Тогда он сделается его рабом навсегда.","7":"Если один человек продал свою дочь в рабство другому, то она не может уйти от хозяина так, как уходят рабы – мужчины.","8":"Если она не понравится хозяину – а он предназначал ее себе в жены – то пусть позволит ее выкупить; он не вправе, отвергнув ее, продать ее чужим.","9":"Если он предназначил ее в жены своему сыну, пусть обращается с ней, как с дочерью.","10":"Если хозяин возьмет себе другую жену, то пусть сохранит за той прежнюю долю мяса, одежды и место в доме.","11":"А если он не сохранит за нею этих трех вещей, то она может уйти от него без выкупа.","12":"Всякий, кто ударит человека так, что тот умрет, должен быть предан смерти.","13":"Если ударивший не замышлял убийства (так уж получилось по воле Божьей), то он может найти убежище; Я назначу вам место для этого.","14":"Но если он убил намеренно, то предай его смерти, даже если будет искать защиты возле Моего жертвенника.","15":"Всякий, кто ударит отца или мать, должен быть предан смерти.","16":"Всякий, кто украдет человека и продаст его (либо у него найдут украденного), должен быть предан смерти.","17":"Всякий, кто оскорбит отца или мать, должен быть предан смерти.","18":"Если во время ссоры один человек ударил другого камнем или кулаком, но тот остался жив, хотя и слег,","19":"а потом поднялся и выходит из дому опираясь на костыль, то ударивший не подлежит наказанию: он должен лишь оплатить время, что тот проболел, и обеспечить ему лечение.","20":"Если хозяин ударит палкой раба или рабыню и те умрут на месте – с него нужно взыскать за эту смерть.","21":"Но если раб или рабыня проживут после этого еще день или два, то за их смерть взыскивать не нужно: раб – это имущество хозяина.","22":"Если мужчины во время драки заденут беременную женщину и у нее будет выкидыш, но сама она не умрет, то пусть виновный заплатит за выкидыш – столько, сколько назначит муж этой женщины.","23":"А если женщина умрет, то ты должен отдать жизнь за жизнь.","24":"Глаз за глаз. Зуб за зуб. За руку – рука. За ногу – нога.","25":"Ожог за ожог. Рана за рану. Ушиб за ушиб.","26":"Если хозяин ударит раба или рабыню и повредит им глаз, то за этот глаз он должен отпустить их на свободу.","27":"И если хозяин выбьет зуб у раба или рабыни, то за этот зуб он должен отпустить их на свободу.","28":"Если бык забодает насмерть мужчину или женщину, то быка нужно забить камнями. Мясо его есть нельзя. Хозяин быка не в ответе.","29":"Но если бык и прежде был бодлив и хозяина предупреждали об этом, а он не смотрел за быком и тот забодал мужчину или женщину, тогда быка нужно забить камнями, а хозяина предать смерти.","30":"(Если на хозяина наложат выкуп, то пусть он уплатит, сколько будет назначено, и тем выкупит свою жизнь.)","31":"Так же следует поступить, если бык забодает сына или дочь главы семьи.","32":"Если бык забодает раба или рабыню, то хозяин быка должен уплатить хозяину раба тридцать шекелей серебра, а быка нужно забить камнями.","33":"Если хозяин оставит яму для воды открытой или выкопает яму, но не закроет ее, и туда свалится бык или осел,","34":"то хозяин ямы должен возместить стоимость животного, а тушу пусть забирает себе.","35":"Если бык забодает насмерть чужого быка, то пусть их владельцы продадут живого быка, а выручку, как и тушу, поделят поровну.","36":"Но если про быка и прежде знали, что он бодлив, то пусть хозяин, не смотревший за быком, возместит ущерб: отдаст быка за быка. А тушу пусть забирает себе."},"22":{"1":"Если кто – нибудь украдет быка или овцу и зарежет их или продаст, то он должен отдать пять быков за быка и четыре овцы за овцу.","2":"(Если вор был пойман при попытке разобрать стену дома и убит, то убивший неповинен.","3":"Но если это случилось после восхода солнца, то убивший виновен.) А если вору нечем отдать, то пусть его самого продадут в рабство – за кражу.","4":"А если украденное животное найдут у него живым – будь то бык, осел или овца – вор должен отдать двух животных за одно.","5":"Если кто – нибудь допустит потраву чужого поля или виноградника – выгонит скот пастись и скот попортит чужое поле – то он должен возместить ущерб в размере самого лучшего урожая с потравленного поля или виноградника.","6":"Если зажженный огонь перейдет на кустарник, а затем погубит скирды, хлеб на корню или все поле – тот, кто зажег огонь, должен возместить ущерб.","7":"Если один человек даст другому на хранение серебро или вещи, и они будут украдены у того из дома, и вор будет пойман, то вор должен все возместить вдвойне.","8":"А если вор не пойман, то взявший вещи на хранение должен предстать перед Богом, чтобы подтвердилось, что он не посягал на чужое добро.","9":"Во всех тяжбах о быке, осле, овце, одежде – о какой бы то ни было пропавшей собственности, которую опознает истец, – дело должно быть представлено Богу. Тот, кого Бог признает виновным, должен все возместить вдвойне.","10":"Если один человек даст другому своего осла, быка, овцу или другую скотину, чтобы тот посмотрел за ней, а скотина сдохнет, покалечится или будет угнана врагом, и свидетелей при этом не будет,","11":"то пусть их рассудит клятва Господом – чтобы подтвердилось, что тот не посягал на чужое добро. Тогда хозяин скотины пусть возьмет, что от нее осталось, а смотревший за ней не должен возмещать ущерб.","12":"Но если скотина будет украдена, то смотревший за ней обязан возместить ее хозяину ущерб.","13":"Если скотина будет растерзана зверями, то пусть он представит в доказательство ее останки – тогда он не должен возмещать ущерб.","14":"Если один человек возьмет у другого скотину в пользование и скотина, в отсутствие хозяина, покалечится или сдохнет, то взявший ее в пользование должен возместить ущерб.","15":"Если это случилось в присутствии хозяина, то ущерб не возмещается, однако если скотина была взята в пользование за плату, хозяин должен получить плату.","16":"Если мужчина совратит необрученную девушку, он должен уплатить за нее выкуп и взять ее в жены.","17":"Если отец девушки не пожелает выдавать за него дочь, то совративший все равно должен уплатить ему столько, сколько положено за девушек.","18":"Колдунью в живых не оставляй.","19":"Скотоложец должен быть предан смерти.","20":"Всякий, кто приносит жертвы богам (помимо Господа), должен быть предан заклятью и уничтожен.","21":"Не притесняй и не обижай переселенцев – ведь вы и сами были переселенцами в Египте.","22":"Не притесняй вдов и сирот.","23":"Если вы будете их притеснять, то они воззовут ко Мне – Я услышу их жалобы,","24":"разгневаюсь и поражу вас мечом! И тогда уже ваши жены станут вдовами, а дети – сиротами.","25":"Если ты дашь бедняку из Моего народа серебро взаймы, то не требуй процентов, как ростовщик.","26":"Если берешь у ближнего плащ в залог, то верни до захода солнца –","27":"ведь ему больше нечем укрыться, это его одежда. Как ему спать без нее? Он воззовет ко Мне – и Я услышу его, потому что Я милосерден.","28":"Бога не хули, главу рода твоего не кляни.","29":"Не медли с приношением виноградного сусла. Отдавайте Мне своих первенцев.","30":"То же касается и скота, крупного и мелкого: пусть первенец семь дней остается при матери, а на восьмой день отдавай его Мне.","31":"Вы должны быть у Меня людьми святыми: не ешьте мясо животных, растерзанных зверем, отдавайте его собакам."},"23":{"1":"Не повторяй пустые наветы. Не помогай неправому лживым свидетельством.","2":"Не следуй за толпой в неправом деле. На суде не искажай истину в угоду толпе.","3":"Бедняку не оказывай предпочтения на суде.","4":"Если ты встретишь заблудившегося быка или осла, которые принадлежат твоему врагу, ты должен отвести их к хозяину.","5":"Если ты увидишь легшего на землю навьюченного осла, который принадлежит твоему недругу, не оставляй его так – ты должен оставить его с хозяином.","6":"Будь справедлив, когда разбираешь тяжбу бедняка, собрата твоего.","7":"Не поддерживай лживых обвинений, чтобы не осудить на смерть невиновных и праведных. Ведь Я не дам злодею уйти от ответа!","8":"Не бери взяток. Взятка превращает зрячих в слепцов и лишает силы правдивые показания.","9":"Не обижай переселенцев. Вы сами знаете, каково человеку на чужбине, – ведь вы были переселенцами в Египте.","10":"Шесть лет засевай свою землю и собирай с нее урожай,","11":"а на седьмой год оставь ее невозделанной. Пусть едят ее плоды бедняки из твоего народа, а что останется – пусть доедят дикие животные. Так же поступай со своим виноградником и оливковыми деревьями.","12":"Шесть дней трудись, а седьмой день будет для тебя днем покоя, чтобы отдохнули твой вол и осел, чтобы сын твоей рабыни и переселенец могли перевести дух.","13":"Соблюдайте все, что Я вам сказал. Имен других богов не возглашайте: пусть не произносят их ваши уста!","14":"Трижды в год справляй Мои праздники.","15":"Справляй праздник Пресного Хлеба: семь дней, как Я повелел тебе, ешь пресный хлеб – в положенное время, в месяце авиве, когда ты ушел из Египта. Никто не должен появляться предо Мной с пустыми руками!","16":"Справляй праздник Жатвы – первого урожая с засеянного тобою поля. Справляй праздник Сбора Плодов – на исходе года, когда соберешь с полей весь урожай.","17":"Три раза в год все мужчины у вас должны представать пред Владыкой – пред Господом.","18":"Когда приносишь Мне жертву, не допускай, чтобы ее кровь пролилась на дрожжевой хлеб. Жир Моих праздничных жертв не оставляй до утра.","19":"Лучшее из первого урожая твоей земли приноси в дом твоего Бога – Господа. Не вари козленка в молоке его матери.","20":"Смотрите, Я посылаю перед вами ангела, который будет оберегать вас в пути и приведет на то место, что Я приготовил для вас.","21":"Бойтесь его и слушайтесь, не противьтесь ему – он не потерпит вашего неповиновения, ибо в нем пребывает имя Мое.","22":"А если вы будете слушаться его и исполнять все, что Я скажу, то Я буду врагом ваших врагов, недругом ваших недругов.","23":"Ангел, посланный Мною, пойдет впереди и приведет вас к амореям, хеттам, периззеям, ханаанеям, хиввеям, евусеям – и Я истреблю эти народы.","24":"А вы не поклоняйтесь и не служите их богам и по обычаям этих народов не поступайте. Уничтожьте их богов и разбейте их священные камни!","25":"Служите Господу, вашему Богу, – и тогда Я благословлю ваш хлеб и вашу воду и избавлю вас от болезней.","26":"Тогда не будет на вашей земле ни выкидышей, ни бесплодия, и Я дам вам сполна прожить отмеренный вам срок.","27":"Ужас Мой Я пошлю перед вами. Я приведу в смятение все народы на вашем пути и всех ваших врагов обращу в бегство перед вами.","28":"Я пошлю перед вами осиные рои, которые погонят прочь хиввеев, ханаанеев и хеттов.","29":"Но не сразу Я их изгоню, не за один год: иначе земля станет безлюдной и дикие звери одолеют вас.","30":"Я буду изгонять эти народы постепенно, до тех пор, пока вы не станете многочисленны и не овладеете всей страной.","31":"Я сделаю границами ваших владений Чермное море и Филистимское море, Пустыню и Реку. Всех жителей этой земли Я отдам в ваши руки, и вы их изгоните.","32":"Не заключайте договоров ни с ними, ни с их богами!","33":"Эти народы не должны жить на вашей земле – иначе они склонят вас к греху против Меня. Служение их богам будет западней для вас."},"24":{"1":"Господь сказал Моисею: «Взойди к Господу, и возьми с собой Аарона, Надава, Авиуда и семьдесят старейшин Израиля. Поклонитесь Господу издали.","2":"Но к Господу пусть приблизится один лишь Моисей! Никто другой не должен приближаться к Господу, а народ и подниматься на гору не должен».","3":"Моисей пришел к народу, передал все слова Господа и пересказал все законы. И весь народ ответил, как один человек: «Мы будем следовать словам Господа».","4":"Моисей записал все слова Господа, а наутро воздвиг под горой жертвенник и поставил двенадцать священных камней, по числу племен Израиля.","5":"Молодым людям из числа сынов Израилевых он велел привести быков и принести Господу жертвы всесожжения и пиршественные жертвы.","6":"Половину крови Моисей собрал в чаши, другой половиной крови окропил жертвенник,","7":"прочитал народу Книгу договора, и люди сказали: «Мы во всем будем следовать словам Господа».","8":"Тогда Моисей окропил народ жертвенной кровью и сказал: «Это кровь договора, который заключил с вами Господь. Его слова – условия договора».","9":"Затем Моисей, Аарон, На дав, Авиуд и семьдесят старейшин Израиля взошли на гору","10":"и там они увидели Бога Израилева. Словно бы сапфировый помост был у Него под ногами – чистый, как само небо.","11":"И Бог не тронул вождей Израиля: они видели Бога – и ели и пили за трапезой.","12":"Господь сказал Моисею: «Взойди ко Мне на гору: там Я дам тебе каменные таблички с правилами и заповедями, которые Я написал для этого народа».","13":"И Моисей вместе со своим помощником Иисусом, поднялся на гору Божью.","14":"«Побудьте здесь, пока мы не вернемся, – сказал Моисей старейшинам. – С вами остаются Аарон и Ор. Если будет у кого какое дело, пусть обращается к ним».","15":"Сам же Моисей взошел на гору. Облако окутывало гору:","16":"это Слава Господня пребывала на горе Синай. Шесть дней гора была окутана облаком, а на седьмой день Господь воззвал к Моисею из облака.","17":"Словно пламя, горящее на вершине горы, предстала Слава Господня глазам сынов Израилевых.","18":"Моисей вошел в облако, поднялся на гору и пробыл там сорок дней и сорок ночей."},"25":{"1":"Господь сказал Моисею:","2":"Вели сынам Израилевым собрать для Меня пожертвования: пусть всякий даст, что пожелает.","3":"Собирайте такие пожертвования: золото, серебро, медь,","4":"голубую, пурпуровую и багряную пряжу, тонкий лен и козью шерсть,","5":"дубленые бараньи шкуры и тонко выделанную кожу, древесину акации,","6":"оливковое масло для светильника, благовония для масла помазания и для воскурений,","7":"камни шохам и драгоценные камни для вставки в оправу, чтобы украсить ими эфод и нагрудник.","8":"Пусть сыны Израилевы построят для Меня святилище, чтобы Я жил среди них.","9":"Вы должны сделать Мое жилище – Скинию – и все, что в ней, в точности так, как Я покажу тебе.","10":"Пусть сделают ковчег из акации, два с половиной локтя длиной, полтора – шириной и полтора – высотой.","11":"Покрой его чистым золотом изнутри и снаружи и обведи золотой каймой.","12":"Сделай четыре золотых кольца и прикрепи их к четырем ножкам ковчега: два кольца с одной стороны ковчега и два – с другой.","13":"Сделай шесты из акации, покрой их золотом","14":"и вставь в кольца по обе стороны ковчега, чтобы носить его на шестах.","15":"Эти шесты всегда должны быть вставлены в кольца ковчега – их нельзя оттуда вынимать.","16":"В ковчег ты положишь текст Завета, который Я вручу тебе.","17":"Сделай для ковчега навершие из чистого золота, два с половиной локтя длиной и полтора локтя шириной.","18":"По краям навершия сделай двух херувимов золотой чеканки:","19":"одного – с одного края, другого – с другого края. Они должны составлять с навершием единое целое.","20":"Стоя друг к другу лицом и глядя на навершие, они должны простирать над ним крылья.","21":"Поставь навершие на ковчег, а в ковчег положи текст Завета, который Я тебе вручу.","22":"Там, над навершием ковчега Завета, меж двух херувимов, буду Я пребывать во время встречи с тобою, возвещая через тебя Мои повеления сынам Израилевым.","23":"Сделай стол из акации, два локтя длиной, локоть шириной и полтора локтя высотой.","24":"Покрой его чистым золотом и обведи золотой каймой.","25":"По краям его сделай стенку, высотой в ладонь, и обведи эту стенку золотой каймой.","26":"Сделай четыре золотых кольца и укрепи их по четырем углам стола, над ножками.","27":"Кольца должны прилегать к стенке; в них будут вставляться шесты, когда нужно будет переносить стол.","28":"Шесты для ношения стола сделай из акации и покрой их золотом.","29":"Сделай из чистого золота блюда, ковши, кувшины и чаши – для возлияний.","30":"На этот стол ты должен регулярно класть хлеб, что будет лежать пред лицом Моим.","31":"Сделай светильник, чеканный, из чистого золота. Его ствол, ветви и чашечки – основания чашечек и лепестки – должны составлять единое целое.","32":"У него должно быть шесть ветвей: три с одной стороны и три – с другой.","33":"На каждой из шести ветвей – по три чашечки, как цветок миндаля, с основанием и лепестками.","34":"На самом же светильнике – четыре цветка, как цветок миндаля, с основанием и лепестками.","35":"Под первой парой ветвей – основание чашечки, под второй парой – основание чашечки, и под третьей парой – основание чашечки; так должно быть под всеми шестью ветвями светильника.","36":"И основания чашечек, и ветви – одно целое со светильником; все должно быть чеканным, из чистого золота.","37":"Сделай семь ламп и расставь их на светильнике, чтобы освещать пространство перед ним.","38":"Щипцы для фитилей и кадильницы должны быть из чистого золота.","39":"На светильник и на все его принадлежности отпусти один талант чистого золота.","40":"Смотри, сделай все в точности так, как тебе было показано на горе ."},"26":{"1":"Сотки для скинии десять полотнищ из тонкого льна, голубой, пурпуровой и багряной пряжи; на них должны быть вытканы херувимы.","2":"Длина каждого полотнища – двадцать восемь локтей, а ширина – четыре локтя; все они должны быть одного размера.","3":"Пять полотнищ пусть будут сшиты вместе, в один кусок, и пять других – тоже сшиты вместе.","4":"Вдоль крайнего полотнища одного куска сделай голубые петли, и такие же петли – вдоль крайнего полотнища другого куска.","5":"Пятьдесят петель должно быть на крайнем полотнище одного куска и пятьдесят – на крайнем полотнище другого куска, петля напротив петли.","6":"Сделай пятьдесят золотых застежек и скрепи оба куска в одно целое – скинию.","7":"Сотки из козьей шерсти одиннадцать полотнищ – покров скинии.","8":"Длина каждого полотнища – тридцать локтей, а ширина – четыре локтя; все одиннадцать – одного размера.","9":"Пять из них сшей вместе, и шесть остальных сшей вместе (шестое сложи пополам – оно будет свисать над входом).","10":"Вдоль крайнего полотнища одного куска сделай пятьдесят петель, и пятьдесят петель – вдоль крайнего полотнища другого куска.","11":"Сделай пятьдесят медных застежек, вставь их в петли и скрепи оба куска, чтобы получился единый покров.","12":"Избыток по длине покрова (полполотнища) должен прийтись на заднюю стену скинии,","13":"а избыток по длине полотнищ (локоть с одной стороны и локоть с другой) – на боковые стены скинии, чтобы полностью покрыть ее.","14":"Сверху сделай покрытие из дубленых бараньих шкур, а поверх него – покрытие из тонко выделанной кожи.","15":"Сделай для скинии рамы из акации:","16":"каждая рама – десять локтей длиной и полтора локтя шириной,","17":"каждая – из двух соединенных брусьев. Такими должны быть все рамы скинии.","18":"Для южной стены скинии сделай двадцать рам","19":"и сорок серебряных опор под них – по две опоры под каждую раму, для обоих ее брусьев.","20":"Также и для второй, северной стены скинии сделай двадцать рам","21":"и сорок серебряных опор – по две опоры под каждую.","22":"Для задней, западной стены скинии сделай шесть рам,","23":"а для задних углов – еще две рамы,","24":"которые внизу должны быть раздвоенными, а наверху (там, где первое кольцо) – цельными. Таких рам должно быть две, по одной на каждом углу.","25":"Для этих восьми рам нужно шестнадцать серебряных опор, по две опоры под каждую.","26":"Сделай перекладины из акации: пять – для соединения рам вдоль одной стены скинии,","27":"пять – для соединения рам вдоль второй стены скинии и пять – для ее задней, западной стены.","28":"Средняя перекладина должна соединять рамы от одного конца стены до другого.","29":"Покрой рамы золотом, приделай к ним золотые кольца для крепления перекладин и покрой перекладины золотом.","30":"Воздвигни скинию так, как было показано тебе на горе.","31":"Сотки завесу из голубой, пурпуровой и багряной пряжи и тонкого льна; на ней должны быть вытканы херувимы.","32":"Подвесь ее на четырех столбах из акации, покрытых золотом, с золотыми крюками. Для этих столбов нужны четыре серебряные опоры.","33":"Завеса должна находиться прямо под застежками. Поставь за ней ковчег Завета. Эта завеса будет отделять святилище от святыни святынь.","34":"Поставь навершие на стоящий в святыне святынь ковчег Завета.","35":"Перед завесой поставь стол, а напротив стола – светильник. Светильник должен стоять у южной стены скинии, а стол – у северной.","36":"Сделай полог, который будет закрывать вход в этот шатер. Полог должен быть разноцветным – из голубой, пурпуровой и багряной пряжи и тонкого льна.","37":"Сделай для полога пять столбов из акации, покрытых золотом, с золотыми крюками. Отлей для столбов пять опор из меди."},"27":{"1":"Сделай из акации жертвенник. Пусть он будет квадратным – пять локтей в длину и пять в ширину, а высота его пусть будет три локтя.","2":"На четырех его углах сделай роги – они должны составлять с жертвенником единое целое – и покрой все медью.","3":"Сделай тазы для золы, лопатки, чаши для кропления кровью, вилки для мяса и совки для углей. Всю утварь для жертвенника сделай из меди.","4":"Сделай для жертвенника решетку – медную сетку – и прикрепи к четырем ее углам четыре медных кольца.","5":"Укрепи решетку под окаймлением жертвенника, так чтобы она доходила до середины жертвенника.","6":"Сделай для жертвенника шесты из акации и покрой их медью.","7":"Когда будет нужно перенести жертвенник, эти шесты будут вставляться в кольца, что у него по бокам.","8":"Сделай жертвенник полым, из досок. Пусть сделают его так, как было показано тебе на горе .","9":"Вокруг скинии сделай двор. С южной стороны, вдоль двора, должна идти завеса из тонкого льна, длиной сто локтей,","10":"на двадцати столбах. Под столбы нужно двадцать медных опор; крюки и соединения на столбах должны быть серебряными.","11":"С северной стороны, вдоль двора, также должна идти завеса длиной сто локтей, на двадцати столбах. Под столбы нужно двадцать медных опор; крюки и соединения на столбах должны быть серебряными.","12":"С западной стороны, по ширине двора, должна идти завеса длиной пятьдесят локтей, на десяти столбах. Под столбы нужно десять опор.","13":"С востока ширина двора должна быть пятьдесят локтей.","14":"По одну сторону от входа должна идти завеса длиной пятнадцать локтей, на трех столбах, под которые нужны три опоры.","15":"И по другую сторону должна идти завеса длиной пятнадцать локтей, на трех столбах, под которые нужны три опоры.","16":"Сотки для ворот разноцветный полог длиной двадцать локтей из голубой, пурпуровой и багряной пряжи и тонкого льна. В воротах должно быть четыре столба, и под них нужны четыре опоры.","17":"Соединения и крюки на всех столбах вокруг двора должны быть серебряными, а опоры для столбов – медными.","18":"Длина двора – сто локтей, ширина – пятьдесят локтей, высота завесы из тонкого льна – пять локтей. Опоры для столбов должны быть медными.","19":"Все принадлежности скинии, колышки для скинии и колышки для завесы вокруг двора должны быть медными.","20":"Вели сынам Израилевым приносить тебе чистое, вручную приготовленное оливковое масло для светильника – чтобы на нем всегда стояли горящие лампы.","21":"Аарон и его сыновья должны следить за тем, чтобы с вечера до утра горящие лампы стояли пред лицом Господа, в Шатре Встречи, перед завесой, за которой находится Завет. Сыны Израилевы должны соблюдать это предписание вечно, из рода в род."},"28":{"1":"Призови к себе из сынов Израилевых твоего брата Аарона и его сыновей, чтобы они стали Моими священниками – Аарон и его сыновья Надав, Авиуд, Элеазар и Итамар.","2":"Сделай своему брату Аарону священные одежды – для величия и красоты.","3":"Вели умельцам, которых Я наделил мастерством, изготовить для Аарона эти одежды, чтобы освятить его и чтобы он служил Моим священником.","4":"Пусть они изготовят нагрудник, эфод, ризу, узорчатую рубаху, тюрбан и пояс – сделают священные одежды для твоего брата Аарона и его сыновей, чтобы они служили Моими священниками.","5":"Пусть возьмут для этого золото, голубую, пурпуровую и багряную пряжу и лен.","6":"Пусть сделают эфод из золотой нити, голубой, пурпуровой и багряной пряжи и тонкого льна, с вытканным орнаментом.","7":"По сторонам к нему должны быть пришиты два наплечника.","8":"Поясок эфода должен быть соткан так же, как и сам эфод, – из золотой нити, голубой, пурпуровой и багряной пряжи и тонкого льна; он должен составлять с эфодом единое целое.","9":"Возьми два камня шохам и вырежи на них имена сыновей Израиля:","10":"шесть имен на одном камне и шесть – на другом, в порядке старшинства.","11":"Вырежи на них имена сыновей Израиля – так, как резчики по камню режут печати. Вставь эти камни в узорчатые оправы из золота","12":"и прикрепи к наплечникам эфода; эти камни – напоминание о сыновьях Израиля. Пусть Аарон носит на плечах, пред Господом, их имена – как напоминание.","13":"Сделай узорчатые оправы из золота,","14":"сделай две цепочки из чистого золота – витые, как шнуры, – и прикрепи цепочки к оправам.","15":"Сделай нагрудник жребиев. Сделай его так же, как эфод, – из золотой нити, голубой, пурпуровой и багряной пряжи и тонкого льна, с вытканным орнаментом.","16":"Пусть нагрудник будет квадратным, длиной в ладонь и шириной в ладонь, из сложенной вдвое ткани.","17":"Сделай на нем гнезда для четырех рядов драгоценных камней. В первом ряду – рубин, хризолит и изумруд;","18":"во втором – бирюза, сапфир и гагат;","19":"в третьем – яхонт, агат и халцедон;","20":"в четвертом – топаз, шохам и яшма. Все они должны быть в узорчатых золотых оправах.","21":"Камней должно быть двенадцать, с именами сыновей Израиля: на каждом камне, как на печати, должно быть вырезано имя одного из двенадцати племен Израиля.","22":"Сделай для нагрудника цепочки из чистого золота – витые, как шнуры.","23":"Сделай два золотых кольца и, укрепив их по углам нагрудника,","24":"соедини двумя золотыми цепочками","25":"с двумя оправами, а оправы эти прикрепи к наплечникам эфода, спереди.","26":"Сделай еще два золотых кольца и прикрепи их к двум углам нагрудника с внутренней стороны, там, где он прилегает к эфоду.","27":"Сделай еще два золотых кольца и прикрепи их спереди к нижнему краю наплечников – там, где они пришиты, сверху, к пояску эфода.","28":"Пусть кольца нагрудника будут связаны голубым шнурком с кольцами эфода, так чтобы нагрудник, находясь над пояском эфода, вплотную прилегал к эфоду.","29":"Пусть Аарон, входя в святилище, носит на груди – на нагруднике – имена сыновей Израиля, как постоянное напоминание о них пред Господом.","30":"В нагрудник указаний вложи урим и туммим: они должны быть на груди Аарона, когда он предстает пред Господом. Пусть Аарон, находясь пред Господом, постоянно носит на груди жребии сынов Израилевых.","31":"Сотки ризу под эфод – сплошь из голубой пряжи.","32":"В ней должен быть вырез для головы, с прочно вытканным краем, как у воинского облачения, чтобы риза не рвалась.","33":"По нижнему краю сделай из голубой, пурпуровой и багряной пряжи шарики в виде гранатовых плодов, а между ними подвесь золотые колокольчики.","34":"Эти золотые колокольчики и гранатовые плоды должны идти, чередуясь, вдоль всего нижнего края ризы.","35":"Пусть Аарон надевает эту ризу, когда будет совершать свое служение. Звон колокольчиков должен быть слышен, когда Аарон входит в святилище, к Господу, и когда он выходит оттуда, – иначе он умрет.","36":"Сделай золотой цветок и вырежи на нем, как на печати, слова: «СВЯТЫНЯ ГОСПОДНЯ».","37":"Прикрепи к нему голубой шнурок, чтобы привязывать его поверх тюрбана, спереди,","38":"на челе у Аарона. Аарон несет ответ за все погрешности в святынях – за все священные приношения сынов Израилевых, и золотой цветок постоянно должен быть у него на челе, чтобы приношения сынов Израилевых были угодны Господу.","39":"Сотки для Аарона узорчатую рубаху из тонкого льна, сделай ему тюрбан из тонкого льна и сотки разноцветный пояс.","40":"Сотки сыновьям Аарона рубахи, пояса и головные повязки – для величия и красоты.","41":"Облачи твоего брата Аарона и его сыновей в эти одежды. Соверши помазание Аарона и его сыновей оливковым маслом, посвяти их в священники и освяти их. Они будут Моими священниками.","42":"Сделай им льняные штаны от пояса до колен, чтобы прикрывали срам.","43":"Аарон и его сыновья должны носить их, когда входят в Шатер Встречи или приближаются к жертвеннику, совершая богослужение в святилище. Иначе они будут повинны и умрут. Это предписание навеки для Аарона и его потомков."},"29":{"1":"Вот что ты должен сделать, чтобы освятить их, чтобы они стали Моими священниками. Выбери быка и двух баранов без телесного изъяна.","2":"Возьми пресный хлеб, пресные лепешки, смоченные оливковым маслом, пресные коржи, намазанные оливковым маслом, – все это должно быть испечено из лучшей, пшеничной, муки –","3":"и сложи их в одну корзину. Принеси эту корзину, приведи быка и двух баранов.","4":"Приведи Аарона с сыновьями ко входу в Шатер Встречи. Омой их.","5":"Облачи Аарона в его одежды – в рубаху, ризу под эфод, эфод и нагрудник. Обвяжи его пояском эфода.","6":"Возложи на голову Аарона тюрбан, а к тюрбану прикрепи венец святыни.","7":"Соверши помазание: возьми оливковое масло для помазания и возлей на голову Аарона.","8":"Приведи сыновей Аарона и надень на них рубахи.","9":"Опояшь Аарона и его сыновей поясами и повяжи им головные повязки. Отныне и навеки священническое звание принадлежит Аарону и его сыновьям. Так ты посвятишь их в священники.","10":"Приведи быка к Шатру Встречи, и пусть Аарон с сыновьями возложат руки на его голову.","11":"Заколи быка пред Господом у входа в Шатер,","12":"омочи палец в крови быка и помажь ею роги жертвенника, а остаток крови вылей к подножию жертвенника.","13":"Потом возьми весь жир с внутренностей быка, отросток печени и обе почки с жиром и сожги на жертвеннике.","14":"А мясо и шкуру быка и его нечистоты предай огню вне стана. Это очистительная жертва.","15":"Затем возьми одного из баранов, и пусть Аарон с сыновьями возложат руки на его голову.","16":"Заколи барана и окропи жертвенник кровью со всех сторон.","17":"Разрежь тушу барана на части. Вымой его внутренности и ноги, положи поверх головы и прочих частей","18":"и сожги всю тушу на жертвеннике. Это жертва всесожжения для Господа, аромат, приятный для Него, дар Господу.","19":"Возьми второго барана, и пусть Аарон с сыновьями возложат руки на его голову.","20":"Заколи барана. Кровью барана помажь Аарону и его сыновьям мочку правого уха, большой палец правой руки и большой палец правой ноги. Окропи жертвенник кровью со всех сторон.","21":"Потом возьми кровь с жертвенника и масло для помазания и окропи ими Аарона и его одежды, а также сыновей Аарона и их одежды. Так ты освятишь Аарона и его одежды, а также сыновей Аарона и их одежды.","22":"Возьми жир и курдюк барана, жир с внутренностей, отросток печени и обе почки с жиром. Поскольку этот баран – посвятительная жертва, то возьми также и его правое бедро.","23":"Возьми один хлеб, одну лепешку, смоченную оливковым маслом, и один корж из той корзины с пресным хлебом, что поставлена пред Господом.","24":"Дай все это в руки Аарону и его сыновьям и вознеси пред Господом как дар.","25":"Возьми это у них из рук и сожги на жертвеннике, вместе с жертвой всесожжения. Это аромат, приятный для Господа, дар Господу.","26":"Возьми грудь барана – посвятительной жертвы Аарона – и вознеси ее пред Господом как дар. Это твоя доля.","27":"Грудь барана, что была вознесена пред Господом, и бедро, что было поднесено в дар, – те части посвятительной жертвы Аарона и его сыновей, что были вознесены или поднесены в дар, – ты должен провозгласить святыней.","28":"Это подношение сынов Израилевых, доля, которая причитается Аарону и его сыновьям вовеки. (И от своих пиршественных жертв сыны Израилевы тоже должны делать подношение Господу.)","29":"Священные одежды Аарона должны перейти к его потомкам: они наденут их, когда будет совершаться их помазание и посвящение в священники.","30":"Пусть потомок Аарона, когда станет священником после него и будет входить в Шатер Встречи и служить в святилище, носит эти одежды семь дней подряд.","31":"Возьми мясо барана – посвятительной жертвы – и свари на святом месте.","32":"Пусть Аарон с сыновьями ест это мясо, а также находящийся в корзине хлеб, в Шатре Встречи, у входа.","33":"Они должны сами съесть жертвы, принесенные при их очищении, посвящении в священники и освящении. Посторонний этого есть не может: это святыня.","34":"Если мясо или хлеб посвятительной жертвы останется до утра, сожги все, что осталось. Никто не должен этого есть, ибо это святыня.","35":"Сверши над Аароном и его сыновьями все, что Я тебе повелел. Семь дней, день за днем, совершай их посвящение в священники.","36":"Каждый день закалывай быка, как очистительную жертву, принесенную для искупления: так ты будешь совершать обряд очищения и искупления жертвенника; совершай помазание жертвенника, чтобы освятить его.","37":"Семь дней, день за днем, совершай очищение жертвенника и освящай его – и жертвенник станет святыней святынь. Все, что коснется его, станет святыней.","38":"Вот жертва, которую ты должен регулярно приносить на этом жертвеннике: два годовалых ягненка в день.","39":"Одного приноси в жертву утром, а второго вечером.","40":"С первым ягненком приноси в жертву одну десятую эфы пшеничной муки, смочив ее четвертью гина вручную приготовленного оливкового масла, и совершай возлияние – четверть гина вина.","41":"Второго ягненка приноси в жертву вечером, с таким же хлебным приношением и таким же возлиянием, как и утром. Это аромат, приятный Господу, дар Господу.","42":"Это всесожжение вы должны совершать регулярно, из рода в род, пред Господом, у входа в Шатер Встречи, где Я буду пребывать во время встречи с вами и говорить с тобою.","43":"Там Я буду пребывать во время встречи с сынами Израилевыми – и освятится то место Славой Моей.","44":"Я освящу Шатер Встречи и жертвенник, освящу Аарона с сыновьями, чтобы они были Моими священниками.","45":"Я буду обитать среди сынов Израилевых и буду их Богом.","46":"И они будут помнить, что Я, Господь, – их Бог, который вывел их из Египта, чтобы обитать среди них. Я, Господь, – их Бог!"},"30":{"1":"Сделай из акации жертвенник для воскурения благовоний.","2":"Пусть он будет квадратным, локоть в длину и локоть в ширину, а высота его пусть будет два локтя. Его роги должны составлять с ним единое целое.","3":"Покрой чистым золотом его верх, стороны и роги – и обведи его золотой каймой.","4":"Сделай два золотых кольца и прикрепи их под каймой, по бокам, чтобы вставлять в них шесты для ношения жертвенника.","5":"Сделай шесты из акации и покрой их золотом.","6":"Поставь этот жертвенник перед завесой, за которой находится ковчег Завета, – пред навершием, над которым Я буду пребывать во время встречи с тобой.","7":"Пусть Аарон воскуряет на этом жертвеннике благовония – каждое утро, когда приходит поправлять лампы,","8":"и каждый вечер, когда приходит зажечь их. Это воскурение благовоний пред Господом должно совершаться регулярно, из рода в род.","9":"Не совершайте на этом жертвеннике ни иных воскурений, ни всесожжении, ни хлебного приношения, ни возлияния.","10":"Пусть раз в год Аарон совершает над рогами жертвенника искупительный обряд. Раз в год, из рода в род, надо совершать искупление жертвенника кровью очистительной жертвы, принесенной для его искупления. Это святыня святынь у Господа.","11":"Господь сказал Моисею:","12":"«Когда будешь делать перепись сынов Израилевых, пусть каждый, при пересчете, даст Господу выкуп за себя, чтобы не постигло их бедствие из – за переписи.","13":"Пусть каждый, при пересчете, внесет полшекеля в шекелях святилища (в шекеле – двадцать гер); эти полшекеля – пожертвование Господу.","14":"Каждый, от двадцати лет и старше, должен при пересчете принести такое пожертвование Господу.","15":"Когда вы приносите Господу это пожертвование, как выкуп за себя, пусть богатый не дает больше, а бедный – меньше, чем полшекеля.","16":"Бери у сынов Израилевых этот выкуп и употребляй его для работ при Шатре Встречи. Это напоминание о сынах Израилевых пред Господом, это выкуп за вас».","17":"Господь сказал Моисею:","18":"«Сделай медный чан для омовений и медную подставку под него. Поставь его между Шатром Встречи и жертвенником и наполни водой.","19":"Пусть Аарон и его сыновья омывают в нем руки и ноги.","20":"Прежде чем войти в Шатер Встречи, они должны омываться – иначе они умрут. И перед тем как приблизиться к жертвеннику, чтобы совершить на нем свое богослужение, сжигая жертвы Господу,","21":"они должны омывать руки и ноги – иначе они умрут. Это предписание навеки для Аарона и его потомков, которое они должны соблюдать из рода в род».","22":"Господь сказал Моисею:","23":"«Возьми лучшие благовония: пятьсот шекелей текучей мирры, благовонной корицы вдвое меньше – двести пятьдесят шекелей, душистого тростника – двести пятьдесят шекелей,","24":"кассии – пятьсот шекелей (все – в шекелях святилища), а также один гин оливкового масла –","25":"и сделай искусно приготовленный состав, священное масло для помазания. Это священное масло –","26":"помажь им Шатер Встречи, ковчег Завета,","27":"стол со всеми сосудами, светильник с его принадлежностями, жертвенник для воскурений,","28":"жертвенник для всесожжении и его утварь и чан с подставкой.","29":"Освяти все это – и оно станет святыней святынь. Все, что коснется этих предметов, станет святыней.","30":"Помажь Аарона с сыновьями – освяти их, чтобы они стали Моими священниками.","31":"А сынам Израилевым скажи: „Этот состав будет у вас священным маслом помазания, из рода в род.","32":"Им нельзя умащать посторонних. Не делайте для себя подобного состава: это святыня – пусть он будет для вас святыней!","33":"Всякий, кто сделает для себя подобный состав или умастит им постороннего, будет истреблен и отторгнут от народа своего\"».","34":"Господь велел Моисею: «Возьми душистые вещества – натаф, шехелет и галбан, пополам с чистым ладаном, –","35":"и сделай из них благовония для воскурений – искусно приготовленный состав, солью приправленный, чистый, священный.","36":"Мелко истолки эти благовония и помести перед Заветом, в Шатре Встречи, где Я буду являться тебе. Эти благовония будут для вас святыней святынь.","37":"Не делайте таких благовоний для себя: пусть они будут у вас святыней Господней.","38":"Всякий, кто сделает такие благовония, чтобы самому вдыхать их запах, будет истреблен и отторгнут от народа своего»."},"31":{"1":"Господь сказал Моисею:","2":"«Знай: Я избрал Бецалела, сына Ури, сына Хура, из племени Иуды,","3":"и исполнил его духом Божьим – дал ему мудрость и разумение, знание и мастерство во всяком деле,","4":"так что он владеет искусством работы по золоту, серебру и меди,","5":"умеет резать камни для вставки в оправу, а также резать по дереву – владеет всяким ремеслом.","6":"Я дал ему в помощники Оголиава, сына Ахисамаха, из племени Дана, и всех умельцев наделил мастерством. Пусть они сделают все, что Я тебе повелел сделать:","7":"Шатер Встречи, ковчег Завета, навершие ковчега и все принадлежности Шатра,","8":"стол и его сосуды, светильник из чистого золота и все его принадлежности, жертвенник для воскурений,","9":"жертвенник для всесожжении и его утварь, чан с подставкой,","10":"одежду для служения – священные одежды Аарона – священника и священнические одежды его сыновей,","11":"а также масло для помазания и благовония для воскурений в святилище. Они должны сделать все так, как Я тебе повелел».","12":"Господь велел Моисею:","13":"«Скажи сынам Израилевым, чтобы они соблюдали Мои субботы. Из рода в род суббота будет знаком, установленным между Мною и вами, чтобы вы помнили, что Я, Господь, освятил вас.","14":"Соблюдайте субботу: она для вас – святыня. Кто осквернит субботу, тот должен быть предан смерти; всякий, кто работает в субботу, будет отторгнут от своего рода.","15":"Шесть дней пусть работают, а седьмой день – суббота, день покоя, святыня Господня. Каждый, кто работает в субботу, должен быть предан смерти.","16":"Пусть сыны Израилевы соблюдают субботу из рода в род – это вечный договор.","17":"Таков знак, установленный навеки между Мною и сынами Израилевыми. Ибо за шесть дней Господь создал небо и землю, а на седьмой день пребывал в покое и отдыхал».","18":"Там, на Синае, кончив говорить с Моисеем, Господь дал ему две таблички Завета – две каменные таблички, исписанные перстом Божьим."},"32":{"1":"Люди видели, что Моисей все не возвращается с горы. Тогда они обступили Аарона и потребовали от него: «Сделай нам бога, который поведет нас за собой. А этот человек, который вывел нас из Египта, – Моисей – мы не знаем, что с ним случилось!»","2":"Аарон велел им: «Выньте серьги из ушей ваших жен, сыновей и дочерей и принесите мне».","3":"Люди вынули из ушей золотые серьги и отдали Аарону.","4":"Аарон взял их, переплавил, сделал статую тельца, и люди сказали друг другу: «Это Бог твой, Израиль! Это Он тебя вывел из Египта!»","5":"Увидев это, Аарон воздвиг перед тельцом жертвенник и провозгласил: «Завтра праздник Господень!»","6":"На следующий день, утром, они принесли жертвы всесожжения и пиршественные жертвы. Потом стали есть и пить, а после принялись вовсю веселиться.","7":"«Спускайся с горы, – сказал Господь Моисею. – Негодным стал твой народ – народ, выведенный тобой из Египта!","8":"Как быстро свернули они с пути, на который Я их наставил! Они сделали себе статую тельца, они поклоняются этому тельцу, и приносят ему жертвы, и говорят: „Это Бог твой, Израиль! Это Он тебя вывел из Египта!\"»","9":"Господь сказал Моисею: «Я вижу, что это народ упрямый!","10":"Не препятствуй Мне излить на них Мой гнев и уничтожить их – а от тебя Я произведу великий народ!»","11":"Но Моисей стал умолять Господа, Бога своего. «Господь! – сказал он. – Зачем Тебе гневаться на Твой народ, который Ты вывел из Египта Своей великой силой – могучей рукой Своей?","12":"Зачем нужно, чтобы египтяне говорили, будто Ты увел этот народ на погибель – уничтожил его в горах, стер с лица земли? Не гневайся, смилуйся, не губи Свой народ!","13":"Вспомни, о чем Ты поклялся Твоим рабам Аврааму, Исааку и Израилю, – Ты поклялся Самим Собой, что сделаешь их потомков многочисленными, как звезды на небе, а землю, которую Ты обещал им, отдашь их потомкам в вечное владение!»","14":"И Господь отменил то наказание, о котором говорил и которому хотел подвергнуть Свой народ.","15":"Моисей повернулся и стал спускаться с горы. В руках у него были две таблички Завета – с письменами на обеих сторонах.","16":"Самим Богом были сделаны эти таблички, и письмена на них были начертаны Богом – вырезаны на табличках.","17":"И тут Иисус услышал, какой шум подняли люди внизу. «В стане шум битвы!» – сказал он Моисею.","18":"Моисей ответил: «Это не гул победы, это не гул пораженья! Я слышу разгульные песни!»","19":"Приблизившись к стану, Моисей увидел тельца и увидел пляски. Разгневался Моисей, бросил таблички наземь, у подножья горы, и разбил их.","20":"Статую тельца он сжег и в порошок растер. А порошок бросил в воду и заставил сынов Израилевых пить ее.","21":"«Чем провинился перед тобой этот народ, что ты вовлек его в такой тяжкий грех?» – спросил Моисей у Аарона.","22":"Аарон ответил: «Не гневайся, господин мой! Ты сам знаешь, что этот народ склонен к злу…","23":"Они говорили мне: „Сделай нам бога, который поведет нас за собой. А этот человек, который вывел нас из Египта, – Моисей – мы не знаем, что с ним случилось!\"","24":"Я велел им отдать мне золотые украшения, бросил золото в огонь… Получился вот этот телец…»","25":"Моисей увидел, что люди забыли стыд и страх, – из – за Аарона, который, врагам на радость, позволил народу позабыть стыд и страх.","26":"Встал Моисей в воротах стана и воззвал: «Кто за Господа? Все ко мне!» Вокруг него собрались все сыны Левиевы,","27":"и Моисей сказал им: «Так говорит Господь, Бог Израиля: „Возьмите мечи и пройдите по стану, от ворот к воротам! Пусть каждый убьет брата, убьет друга, убьет соседа!\"»","28":"Сыны Левиевы выполнили приказ Моисея: около трех тысяч человек было убито в тот день.","29":"Моисей сказал им так: «Посвятите себя ныне в священники Господа – ценой сына, ценой брата, и тогда вам будет дано благословение!»","30":"На следующий день Моисей сказал народу: «Тяжек ваш грех! Но я взойду к Господу, и быть может, мне удастся загладить вашу вину».","31":"Вернувшись к Господу, Моисей сказал: «Тяжек грех этого народа: они сделали себе бога из золота!","32":"Простишь ли Ты их? Если нет – то сотри и меня из Книги Твоей!»","33":"Господь ответил: «Я сотру из Книги Моей тех, кто согрешил против Меня.","34":"Ступай и приведи народ в назначенное Мною место. Мой ангел будет идти перед тобой. А когда настанет день наказанья, Я накажу их за грех».","35":"(Господь покарал народ Израилев за то, что они сделали тельца – того тельца, которого изготовил Аарон.)"},"33":{"1":"Господь сказал Моисею: «Уходи отсюда, вместе с народом, который ты вывел из Египта. Идите в ту землю, о которой Я клялся Аврааму, Исааку и Иакову, что отдам ее их потомкам.","2":"Я пошлю перед тобою Моего ангела и изгоню прочь ханаанеев, амореев, хеттов, периззеев, хиввеев и евусеев.","3":"Идите в эту землю, источающую молоко и мед! Но Сам Я с вами не пойду, а иначе в пути Я уничтожу вас за ваше упрямство!»","4":"Услышали люди эти грозные слова – и зарыдали, и сняли с себя украшения.","5":"Господь сказал Моисею: «Передай сынам Израилевым: вы народ упрямый, и если Я с вами пойду, то истреблю вас в одно мгновенье! Снимите с себя украшения. А Я посмотрю, что Мне с вами делать».","6":"(Там, у горы Хорив, сыны Израилевы сняли украшения – и больше их не надевали.)","7":"С тех пор Моисей ставил поодаль от стана шатер, который называл Шатром Встречи. Если кому – нибудь нужно было вопросить Господа, то Моисей выходил из стана и шел к Шатру Встречи.","8":"Он шел, а все стояли у своих шатров и провожали его взглядом, пока он не входил в Шатер Встречи.","9":"Он входил; облачный столп опускался, стоял у входа в Шатер, и Господь говорил с Моисеем.","10":"Увидев облачный столп, все падали ниц у своих шатров.","11":"Господь говорил с Моисеем лицом к лицу – как говорит человек с человеком. Потом Моисей возвращался в стан, а Иисус Навин, помощник Моисея, не покидал Шатра.","12":"Моисей сказал Господу: «Ты велел мне вести этот народ дальше, но не сказал, кого пошлешь со мною. Ты говорил мне, что помнишь имя мое, что я угоден Тебе.","13":"Если так, то поведай мне пути Твои, дай познать Тебя, чтобы я делал угодное Тебе. Ведь эти люди – Твой народ!»","14":"Господь ответил: «Я Сам пойду с вами и буду тебе помогать».","15":"Моисей сказал: «Если Ты с нами не пойдешь, то и нас не заставляй уходить отсюда.","16":"Каков знак, что я и этот Твой народ угодны Тебе? Только тот, что Ты пойдешь с нами! Этим Ты покажешь, что отличаешь нас от прочих народов земли».","17":"И Господь ответил Моисею: «Я выполню твою просьбу, ибо ты Мне угоден и Я помню имя твое». –","18":"«Яви мне Славу Твою!» – попросил Моисей.","19":"И Господь обещал: «Все Мое великолепие Я проведу пред тобою, провозглашу пред тобою имя Господне. Я милую тех, кого хочу миловать, Я милосерден с теми, с кем хочу быть милосердным.","20":"Но ты не можешь взглянуть Мне в лицо, – сказал Господь Моисею. – Не может человек увидеть Меня и остаться в живых.","21":"Здесь есть место, вблизи от Меня, – сказал Господь Моисею. – Стань там на скале.","22":"Когда Слава Моя будет проходить мимо, Я спрячу тебя в расщелине этой скалы и накрою Своей рукой. А когда пройду,","23":"то уберу руку. Ты увидишь Меня сзади, а лица Моего не увидишь»."},"34":{"1":"Господь сказал Моисею: «Вытеши из камня две таблички, подобные прежним. Я начертаю на них те же слова, что были на прежних табличках, которые ты разбил.","2":"Будь готов к утру. Утром взойди на гору Синай и предстань предо Мною на вершине горы.","3":"Пусть никто не идет с тобою, пусть никто не показывается на горе, и скот пусть не пасется у ее подножья».","4":"Моисей вытесал из камня две таблички, подобные прежним, а на рассвете, с табличками в руках, поднялся на гору Синай, как повелел ему Господь.","5":"Спустился Господь в облаке, стал перед Моисеем и провозгласил имя Господне.","6":"Прошел Господь перед ним – и провозгласил: «Господь, Господь, Бог милосердный и добрый, терпеливый, милостивый и верный!","7":"Милость Его даже в тысячном поколении неизменна: Он терпит провинности, грехи и преступления. Но виновного Он не признает невинным: Он карает детей за грехи отцов, карает потомков – и внуков и правнуков!»","8":"Моисей поспешно склонился, простерся ниц","9":"и сказал: «Владыка мой! Если я угоден Тебе, то иди с нами, Владыка мой! Да, этот народ упрям, но прости нам наши грехи и преступления! Сделай нас Своим достоянием!»","10":"Господь ответил: «Я заключаю с вами договор. На глазах у всего народа Я сотворю чудеса, каких не было на земле – ни у одного из народов! Пусть весь народ, что тебя окружает, со страхом взирает на дела, которые Я, Господь, делаю через тебя!","11":"Соблюдайте все, что Я ныне повелеваю вам. Я заставлю амореев и ханаанеев, хеттов и периззеев, хиввеев и евусеев бежать от вас прочь.","12":"Смотрите, не заключайте договоров с жителями той земли, куда вы идете, – это будет для вас западней!","13":"Их жертвенники – разрушьте! Их священные камни – разбейте! Дерева Ашеры – срубите!","14":"Чужим богам – не поклоняйтесь! Ибо Господу имя – Ревность! Он – Бог Ревнивый!","15":"Не заключайте договоров с жителями той земли. Они блудят со своими богами – приносят им жертвы. Если они позовут вас к себе, то вы будете есть мясо с их жертвенников.","16":"Их дочери блудят со своими богами. Если вы станете брать их дочерей в жены своим сыновьям, то они и ваших сыновей вовлекут в этот блуд.","17":"Не делай себе статуй божества.","18":"Справляй праздник Пресного Хлеба: семь дней, как Я повелел тебе, ешь пресный хлеб – в положенное время, в месяце авиве, ибо в месяце авиве ты ушел из Египта.","19":"Первый плод всякого материнского чрева принадлежит Мне – все первенцы мужского пола, какие родятся у скота, и крупного и мелкого.","20":"За первенца ослицы отдавай выкуп – овцу, а если не хочешь выкупить – сломай ему шею. И за своих первенцев отдавай выкуп. Никто не должен появляться предо Мной с пустыми руками!","21":"Шесть дней работай, а в седьмой день отдыхай: прерывай работу даже во время пахоты и жатвы.","22":"Справляй праздник Недель – праздник первого урожая пшеницы. Справляй праздник Сбора Плодов, в конце года.","23":"Три раза в год все мужчины у вас должны представать пред Владыкой – пред Господом, Богом Израиля.","24":"Я отдам вам земли других народов, Я расширю твои пределы, и никто не будет посягать на твою землю – если ты будешь три раза в год представать пред Господом, твоим Богом.","25":"Когда приносишь Мне жертву, не допускай, чтобы ее кровь пролилась на дрожжевой хлеб. Жертву, принесенную в праздник Пасхи, не оставляй до утра.","26":"Лучшее из первого урожая твоей земли приноси в дом твоего Бога – Господа. Не вари козленка в молоке его матери».","27":"Господь сказал Моисею: «Запиши эти слова. Это условия договора, который Я заключаю с тобой и с Израилем».","28":"Моисей пробыл с Господом сорок дней и сорок ночей, хлеба не ел и воды не пил. Он записал на табличках условия договора – Десять Заповедей.","29":"Когда Моисей спустился с горы Синай, в руках у него были две таблички Завета. Моисей не знал, что после разговора с Господом от его лица исходят лучи.","30":"Но Аарон и сыны Израилевы увидели это и побоялись к нему приблизиться.","31":"Моисей позвал их. Аарон и вожди общины подошли, и Моисей заговорил с ними.","32":"Затем подошли и остальные сыны Израилевы. Моисей возвестил им все повеления, данные Господом на горе Синай,","33":"а затем закрыл лицо покрывалом.","34":"Всякий раз, приближаясь к Господу, чтобы говорить с Ним, Моисей снимал покрывало с лица. Вернувшись, он возвещал сынам Израилевым, что повелел ему Господь, –","35":"и сыны Израилевы видели, как от его лица исходят лучи. А Моисей вновь закрывал лицо покрывалом, до следующего разговора с Господом."},"35":{"1":"Собрав всю общину сынов Израилевых, Моисей сказал: «Вот что повелел Господь.","2":"Шесть дней работайте, а седьмой день – святыня Господня, суббота, день покоя. Всякий, кто работает в этот день, будет предан смерти.","3":"По субботам даже огня нельзя зажигать в ваших жилищах».","4":"«Вот что повелевает Господь, – сказал Моисей общине сынов Израилевых. –","5":"Соберите пожертвования для Господа. Пусть каждый, кто желает, пожертвует Господу золото, серебро или медь,","6":"голубую, пурпуровую или багряную пряжу, тонкий лен или козью шерсть,","7":"дубленые бараньи шкуры и тонко выделанную кожу, древесину акации,","8":"оливковое масло для светильника, благовония для масла помазания и для воскурений,","9":"камни шохам и драгоценные камни для вставки в оправу, чтобы украсить ими эфод и нагрудник.","10":"Пусть ваши умельцы придут и сделают все, что Господь повелел сделать:","11":"скинию, ее покров и покрытие поверх него, застежки, рамы и перекладины, столбы и опоры,","12":"ковчег и шесты для него, навершие ковчега и завесу,","13":"стол, его шесты и сосуды, хлеб, что будет лежать пред лицом Господа,","14":"светильник и его принадлежности, лампы, масло для светильника,","15":"жертвенник для воскурений и шесты для него, масло для помазания и благовония для воскурений, полог для входа в скинию,","16":"жертвенник для всесожжении с медной решеткой, его шесты и его утварь, чан с подставкой,","17":"завесы двора, его столбы и опоры под них, полог для ворот двора,","18":"колышки для скинии и колышки для завесы вокруг двора, веревки к ним,","19":"одежду для богослужения в святилище – священные одежды Аарона – священника и священнические одежды его сыновей».","20":"Сыны Израилевы разошлись,","21":"а затем каждый принес, что ему сердце велело, что он желал пожертвовать Господу – все нужное для Шатра Встречи, для служения в нем и для священных одежд.","22":"Пришли все, кто хотел, и мужчины и женщины, и принесли золотые украшения: застежки, серьги, кольца, ожерелья. Это золото они, как дар, вознесли перед Господом.","23":"У кого нашлось, те принесли голубую, пурпуровую и багряную пряжу, тонкий лен, козью шерсть, дубленые бараньи шкуры и тонко выделанную кожу.","24":"Кто мог, принес в дар Господу серебро или медь. У кого нашлась пригодная для дела древесина акации, пожертвовали ее.","25":"Женщины – умелицы пряли и приносили голубую, пурпуровую и багряную пряжу и тонкий лен,","26":"а другие женщины – кто умел и пожелал – пряли козью шерсть.","27":"Вожди общины принесли камни шохам и драгоценные камни для вставки в оправу, чтобы украсить ими эфод и нагрудник,","28":"а также благовония и масло – для освещения, помазания и воскурений.","29":"Так все мужчины и женщины народа Израилева, пожелавшие участвовать в том деле, которое Господь, через Моисея, повелел сделать, – принесли Господу свои дары.","30":"Моисей сказал сынам Израилевым: «Знайте: Господь избрал Бецалела, сына Ури, сына Хура, из племени Иуды,","31":"и исполнил его духом Божьим, дал ему мудрость и разумение, знание и мастерство во всяком деле,","32":"так что он владеет искусством работы по золоту, серебру и меди,","33":"умеет резать камни для вставки в оправу, а также резать по дереву – может выполнять любую искусную работу.","34":"Господь дал ему, а также Оголиаву, сыну Ахисамаха, из племени Дана, умение обучать других.","35":"Господь открыл им искусство резьбы, искусство ткать ткани с орнаментом, разноцветные ткани из голубой, пурпуровой и багряной пряжи и тонкого льна, а также простые ткани – все искусства мастеров и умельцев."},"36":{"1":"Бецалел, Оголиав и все умельцы, которым Господь дал мудрость и разумение, чтобы они построили святилище, должны сделать все так, как повелел Господь».","2":"Моисей позвал Бецалела, Оголиава и всех умельцев, которым Господь даровал мастерство, всех, кто желал приступить к работе.","3":"Они взяли у Моисея пожертвования, которые сыны Израилевы принесли для строительства святилища. Однако люди продолжали каждое утро нести все новые и новые дары.","4":"Тогда все умельцы, строившие святилище, оставили работу, пришли","5":"и сказали Моисею: «Люди приносят больше, чем нужно для работы, которую повелел сделать Господь».","6":"Моисей приказал объявить по всему стану, что ни мужчины, ни женщины больше не должны приносить пожертвований для святилища. И у людей перестали принимать дары:","7":"собрано было достаточно – и даже больше, чем нужно.","8":"Приступившие к работе умельцы соткали для скинии десять полотнищ из тонкого льна, голубой, пурпуровой и багряной пряжи; на полотнищах были вытканы херувимы.","9":"Длина каждого полотнища была двадцать восемь локтей, а ширина – четыре локтя; все полотнища были одного размера.","10":"Пять полотнищ сшили вместе, в один кусок, и пять других – тоже сшили вместе.","11":"Вдоль крайнего полотнища одного куска сделали голубые петли, и такие же петли – вдоль крайнего полотнища другого куска:","12":"пятьдесят петель на крайнем полотнище одного куска и пятьдесят – на крайнем полотнище другого куска, петля напротив петли.","13":"Сделали пятьдесят золотых застежек и скрепили оба куска в одно целое – скинию.","14":"Соткали из козьей шерсти одиннадцать полотнищ – покров скинии.","15":"Длина каждого полотнища была тридцать локтей, и четыре локтя – ширина; все одиннадцать были одного размера.","16":"Пять из них сшили вместе, и шесть остальных тоже сшили вместе.","17":"Вдоль крайнего полотнища одного куска сделали пятьдесят петель, и пятьдесят петель – вдоль крайнего полотнища другого куска.","18":"Сделали пятьдесят медных застежек и скрепили оба куска, чтобы получился единый покров.","19":"Сверху сделали покрытие из дубленых бараньих шкур, а поверх него – покрытие из тонко выделанной кожи.","20":"Сделали для скинии рамы из акации:","21":"каждая рама была десять локтей длиной и полтора локтя шириной,","22":"каждая – из двух соединенных брусьев. Такими были все рамы скинии.","23":"Для южной стены скинии сделали двадцать рам","24":"и сорок серебряных опор под них – по две опоры под каждую раму, для обоих ее брусьев.","25":"Также и для второй, северной стены скинии сделали двадцать рам","26":"и сорок серебряных опор – по две опоры под каждую.","27":"Для задней, западной стены скинии сделали шесть рам,","28":"а для задних углов – еще две рамы.","29":"Внизу эти рамы были раздвоенными, а наверху (там, где первое кольцо) – цельными. Таких рам было две, по одной на каждом углу.","30":"Для этих восьми рам сделали шестнадцать серебряных опор: по две опоры под каждую раму.","31":"Сделали перекладины из акации: пять – для соединения рам вдоль одной стены скинии,","32":"пять – для соединения рам вдоль второй стены скинии и пять – для ее задней, западной стены.","33":"Средняя перекладина соединяла рамы от одного конца стены до другого.","34":"Рамы покрыли золотом, приделали к ним золотые кольца для крепления перекладин и покрыли перекладины золотом.","35":"Соткали завесу из голубой, пурпуровой и багряной пряжи и тонкого льна; на завесе были вытканы херувимы.","36":"Сделали для нее четыре столба из акации и покрыли их золотом, изготовили золотые крюки и отлили из серебра четыре опоры для столбов.","37":"Из голубой, пурпуровой и багряной пряжи и тонкого льна сделали разноцветный полог, который должен был закрывать вход в Шатер.","38":"Сделали пять столбов с крюками, покрыли столбы золотом, вверху и внизу, и сделали для них пять опор из меди."},"37":{"1":"Бецалел сделал ковчег из акации, два с половиной локтя длиной, полтора – шириной и полтора – высотой,","2":"покрыл его чистым золотом изнутри и снаружи и обвел золотой каймой.","3":"Он сделал четыре золотых кольца и прикрепил их к четырем ножкам ковчега: два кольца с одной стороны ковчега и два – с другой.","4":"Он сделал шесты из акации, покрыл их золотом","5":"и вставил в кольца по обе стороны ковчега, чтобы носить его на шестах.","6":"Он сделал для ковчега навершие из чистого золота, два с половиной локтя длиной и полтора локтя шириной.","7":"По краям навершия он сделал двух херувимов золотой чеканки:","8":"одного – с одного края, другого – с другого края. Они составляли с навершием единое целое.","9":"Стоя друг к другу лицом и глядя на навершие, они простирали над ним крылья.","10":"Он сделал стол из акации, два локтя длиной, локоть шириной и полтора локтя высотой,","11":"покрыл его чистым золотом и обвел золотой каймой.","12":"По краям его он сделал стенку, высотой в ладонь, и обвел эту стенку золотой каймой.","13":"Он сделал четыре золотых кольца и укрепил их по четырем углам стола, над ножками,","14":"чтобы вставлять в эти кольца шесты, когда нужно будет переносить стол. Кольца прилегали к стенке.","15":"Он сделал из акации шесты для ношения стола и покрыл их золотом.","16":"Он сделал из чистого золота сосуды, которые должны были стоять на столе: блюда, ковши, чаши и кувшины – для возлияний.","17":"Он сделал светильник, чеканный, из чистого золота. Его ствол, ветви и чашечки – основания чашечек и лепестки – составляли единое целое.","18":"У светильника было шесть ветвей: три с одной стороны и три – с другой.","19":"На каждой из шести ветвей было по три чашечки, как цветок миндаля, с основанием и лепестками.","20":"На самом же светильнике было четыре цветка, как цветок миндаля, с основанием и лепестками.","21":"Под первой парой ветвей – основание чашечки, под второй парой – основание чашечки, и под третьей парой – основание чашечки; так было под всеми шестью ветвями.","22":"И основания чашечек, и ветви составляли одно целое со светильником; все было чеканным, из чистого золота.","23":"Он сделал семь ламп, сделал из чистого золота щипцы для фитилей и кадильницы.","24":"На светильник и на все его принадлежности ушел один талант чистого золота.","25":"Он сделал из акации жертвенник для воскурений – квадратный, локоть в длину, локоть в ширину и два локтя в высоту. Роги жертвенника составляли единое целое с жертвенником.","26":"Его верх, стороны и роги он покрыл чистым золотом – и обвел его золотой каймой.","27":"Он сделал два золотых кольца и прикрепил их под каймой, по бокам, чтобы вставлять в них шесты для ношения жертвенника.","28":"Он сделал шесты из акации и покрыл их золотом.","29":"Он приготовил священное масло для помазания и чистый, искусно приготовленный состав – благовония для воскурений."},"38":{"1":"Он сделал из акации жертвенник для всесожжении, квадратный – пять локтей в длину и пять в ширину, а высотой три локтя.","2":"На четырех его углах он сделал роги – они составляли с жертвенником единое целое – и покрыл все медью.","3":"Он сделал утварь для жертвенника: тазы, лопатки, чаши для кропления кровью, вилки для мяса и совки для углей. Всю эту утварь он сделал из меди.","4":"Он сделал для жертвенника решетку – медную сетку – и укрепил ее под окаймлением жертвенника, так что она доходила до середины жертвенника.","5":"Он отлил четыре кольца для шестов и прикрепил их по четырем углам медной решетки,","6":"а сами шесты сделал из акации и покрыл медью.","7":"Шесты он вставил в кольца, что по бокам жертвенника, чтобы его можно было переносить. Жертвенник был сделан полым, из досок.","8":"Он сделал также чан и подставку под него; на это пошла медь тех зеркал, что были у женщин, служивших при входе в Шатер Встречи.","9":"Потом он сделал двор. С южной стороны двора шла завеса из тонкого льна, длиной сто локтей,","10":"на двадцати столбах с двадцатью медными опорами. Крюки и соединения на столбах были серебряными.","11":"С северной стороны двора шла завеса длиной сто локтей, на двадцати столбах с двадцатью медными опорами. Крюки и соединения на столбах были серебряными.","12":"С западной стороны двора шла завеса длиной пятьдесят локтей, на десяти столбах с десятью опорами. Крюки и соединения на столбах были серебряными.","13":"Восточная сторона была пятьдесят локтей в длину.","14":"По одну сторону от входа шла завеса пятнадцать локтей длиной, на трех столбах с тремя опорами.","15":"И по другую сторону от ворот двора также шла завеса длиной пятнадцать локтей, на трех столбах с тремя опорами.","16":"Все завесы вокруг двора были из тонкого льна,","17":"опоры под столбами были медными, а крюки и соединения на столбах – серебряными; верхи столбов были покрыты серебром. Серебряными соединениями были скреплены все столбы двора.","18":"Полог на воротах был разноцветным – из голубой, пурпуровой и багряной пряжи и тонкого льна, длиной двадцать локтей. Его высота была пять локтей, как у завесы двора.","19":"В воротах было четыре столба на четырех медных опорах; крюки на столбах были серебряными. Верхи столбов были покрыты серебром; соединения на них были серебряными.","20":"Все колышки для скинии и колышки для завесы вокруг двора были медными.","21":"Вот перечень затрат на скинию – скинию Завета – составленный по приказу Моисея левитами под началом Итамара, сына Аарона – священника.","22":"(Бецалел, сын Ури, сына Хура, из племени Иуды, сделал все, что повелел Господь, через Моисея.","23":"С ним был Оголиав, сын Ахисамаха, из племени Дана, владеющий искусством резьбы, а также искусством ткать ткани с орнаментом и разноцветные ткани из голубой, пурпуровой и багряной пряжи и тонкого льна.)","24":"Золото, использованное для постройки святилища, – золото приношений – составило двадцать девять талантов и семьсот тридцать шекелей (в шекелях святилища).","25":"Серебро, собранное при переписи общины, составило сто талантов и тысячу семьсот семьдесят пять шекелей (в шекелях святилища):","26":"с каждого сосчитанного, от двадцати лет и старше, – с шестисот трех тысяч пятисот пятидесяти человек – взяли по одной беке (полшекеля в шекелях святилища).","27":"Сто талантов серебра пошло на отливку опор для столбов святилища и столбов его завесы: на сто опор – сто талантов, по одному таланту на опору.","28":"Тысячу семьсот семьдесят пять шекелей серебра употребили на крюки и соединения для столбов и на то, чтобы покрыть верхи столбов серебром.","29":"Медь приношений составила семьдесят талантов и две тысячи четыреста шекелей.","30":"Из нее сделали опоры для столбов при входе в Шатер Встречи, медный жертвенник с решеткой и его утварь,","31":"опоры столбов для завесы вокруг двора и для ворот двора, а также колышки для скинии и для завесы вокруг двора."},"39":{"1":"Из голубой, пурпуровой и багряной пряжи соткали одежды для богослужения в святилище – соткали священные одежды для Аарона. Так повелел Моисею Господь.","2":"Из золота, голубой, пурпуровой и багряной пряжи и тонкого льна сделали эфод.","3":"Для этого золото расплющили в листы и разрезали их на нити, а из этих нитей, голубой, пурпуровой и багряной пряжи и тонкого льна соткали ткань с орнаментом.","4":"По сторонам к эфоду пришили наплечники.","5":"Поясок эфода был соткан так же, как и сам эфод, и составлял с ним единое целое – он был соткан из золотой нити, голубой, пурпуровой и багряной пряжи и тонкого льна. Так повелел Моисею Господь.","6":"Приготовили камни шохам, вставленные в узорчатые оправы из золота; на этих камнях, как на печатях, были вырезаны имена сыновей Израиля.","7":"Их прикрепили к наплечникам эфода, чтобы эти камни были напоминанием о сыновьях Израиля. Так повелел Моисею Господь.","8":"Сделали нагрудник – так же, как эфод, – из золотой нити, голубой, пурпуровой и багряной пряжи и тонкого льна, с вытканным орнаментом.","9":"Нагрудник был квадратным, в пядь длиной и в пядь шириной, из сложенной вдвое ткани.","10":"На нем было четыре ряда драгоценных камней. В первом ряду – рубин, хризолит и изумруд;","11":"во втором – бирюза, сапфир и гагат;","12":"в третьем – яхонт, агат и халцедон;","13":"в четвертом – топаз, шохам и яшма. Все камни были в узорчатых золотых оправах.","14":"Камней было двенадцать, с именами сыновей Израиля: на каждом камне, как на печати, было вырезано имя одного из двенадцати племен Израиля.","15":"Для нагрудника сделали цепочки из чистого золота – витые, как шнуры.","16":"Сделали две узорчатые золотые оправы. Сделали также два золотых кольца и, укрепив их по углам нагрудника,","17":"соединили двумя золотыми цепочками","18":"с двумя оправами, а оправы эти прикрепили к наплечникам эфода, спереди.","19":"Сделали еще два золотых кольца и прикрепили их к двум углам нагрудника с внутренней стороны, там, где он прилегает к эфоду.","20":"Сделали еще два золотых кольца и прикрепили их спереди к нижнему краю наплечников – там, где они пришиты, сверху, к пояску эфода.","21":"Кольца нагрудника были связаны голубым шнурком с кольцами эфода, так что нагрудник, находясь над пояском эфода, вплотную прилегал к эфоду. Так повелел Моисею Господь.","22":"Соткали ризу под эфод – сплошь из голубой пряжи.","23":"В ней был вырез с прочным краем, как у воинского облачения, чтобы риза не рвалась.","24":"По нижнему краю ризы сделали шарики в виде гранатовых плодов из голубой, пурпуровой и багряной пряжи и тонкого льна.","25":"Сделали колокольчики из чистого золота и подвесили их между гранатовыми плодами по всему нижнему краю ризы.","26":"Колокольчики и гранатовые плоды шли, чередуясь, вдоль всего нижнего края ризы для богослужения. Так повелел Моисею Господь.","27":"Для Аарона и его сыновей соткали рубахи из льна,","28":"сделали льняной тюрбан и льняные головные повязки, сделали штаны из тонкого льна.","29":"Соткали разноцветный пояс – из тонкого льна, голубой, пурпуровой и багряной пряжи. Так повелел Моисею Господь.","30":"Сделали венец святыни – золотой цветок – и вырезали на нем, как на печати, надпись: «святыня Господня».","31":"К нему прикрепили голубой шнурок, чтобы привязывать поверх тюрбана. Так повелел Моисею Господь.","32":"И завершилась работа над скинией – Шатром Встречи. Сыны Израилевы сделали все в точности так, как повелел Моисею Господь.","33":"Они принесли Моисею скинию, покров и все их принадлежности – застежки, рамы, перекладины, столбы и опоры –","34":"а также покрытие из дубленых бараньих шкур и покрытие из тонко выделанной кожи, завесу,","35":"ковчег Завета, его шесты, навершие,","36":"стол и его сосуды, хлеб, что будет лежать пред лицом Господа,","37":"светильник из чистого золота и лампы, которые должны стоять на нем, все его принадлежности и масло для него,","38":"золотой жертвенник, масло для помазания, благовония для воскурений, полог для входа в Шатер,","39":"медный жертвенник с медной решеткой, его шесты и его утварь, чан с подставкой,","40":"завесы двора, его столбы и опоры под них, полог для ворот двора, веревки и колышки, всю утварь для служения в скинии – Шатре Встречи –","41":"а также одежду для богослужения в святилище: священные одежды Аарона – священника и священнические одежды его сыновей.","42":"Как повелел Моисею Господь, в точности так сыны Израилевы все и сделали.","43":"Моисей оглядел то, что они сделали, – все было сделано в точности так, как повелел Господь. И Моисей благословил их."},"40":{"1":"Господь сказал Моисею:","2":"«В первый день первого месяца поставь скинию – Шатер Встречи.","3":"Внеси туда ковчег Завета и закрой его завесой.","4":"Внеси туда стол и расставь на нем все, что нужно; принеси светильник и расставь на нем лампы.","5":"Перед ковчегом Завета поставь золотой жертвенник для воскурений. На входе в скинию повесь полог.","6":"Перед входом в скинию – Шатер Встречи – поставь жертвенник для всесожжении.","7":"Между Шатром Встречи и жертвенником поставь чан и наполни его водой.","8":"Вокруг устрой двор, а в воротах двора повесь полог.","9":"Затем возьми масло для помазания и помажь скинию и все, что в ней есть: освяти скинию и всю ее утварь – и они станут святыней.","10":"Помажь также жертвенник для всесожжении и всю его утварь: освяти жертвенник – и он станет святыней святынь.","11":"Помажь чан и его подставку – освяти их.","12":"Потом приведи Аарона с сыновьями ко входу в Шатер Встречи и омой их.","13":"Надень на Аарона священные одежды и помажь его: освяти его, чтобы он стал Моим священником.","14":"Приведи его сыновей, надень на них рубахи,","15":"помажь их, как ты помазал их отца, и они будут Моими священниками. Это помазание будет означать, что священническое звание принадлежит им навеки – из рода в род».","16":"Моисей все сделал в точности так, как повелел ему Господь.","17":"В первый день первого месяца второго года скиния была поставлена.","18":"Моисей поставил скинию: он уложил опоры, установил на них рамы, соединив их перекладинами, установил столбы,","19":"накрыл скинию покровом, а сверху сделал покрытие – как повелел ему Господь.","20":"Моисей взял Завет и положил его в ковчег, прикрепил к ковчегу шесты и возложил на него навершие,","21":"внес ковчег в скинию и повесил завесу, закрыв ею ковчег Завета, – как повелел ему Господь.","22":"В северной части скинии – Шатра Встречи – Моисей поставил перед завесой стол","23":"и разложил на нем хлеб пред Господом – как повелел ему Господь.","24":"В южной части скинии – Шатра Встречи – напротив стола, Моисей установил светильник","25":"и расставил на нем лампы пред Господом – как повелел ему Господь.","26":"В Шатре Встречи, перед завесой, он поставил золотой жертвенник","27":"и воскурил на нем благовония – как повелел ему Господь.","28":"На входе в скинию он повесил полог.","29":"У входа в скинию – Шатер Встречи – он поставил жертвенник для всесожжении и совершил на нем всесожжение и хлебное приношение – как повелел ему Господь.","30":"Между Шатром Встречи и жертвенником он поставил чан и наполнил его водой для омовений.","31":"Моисей, Аарон и сыновья Аарона омывали в нем руки и ноги,","32":"когда им нужно было войти в Шатер Встречи или подойти к жертвеннику, – как повелел Моисею Господь.","33":"Вокруг скинии и жертвенника он устроил двор, а в воротах двора повесил полог. Завершил Моисей свой труд –","34":"и облако скрыло Шатер Встречи, и Слава Господня наполнила скинию.","35":"И не мог он войти в Шатер Встречи, ибо облако окутало Шатер Встречи и Слава Господня наполнила скинию.","36":"Когда это облако над скинией поднималось вверх, сыны Израилевы отправлялись в путь и совершали очередной переход.","37":"Если же облако не поднималось, то они не трогались с места и ждали дня, когда оно поднимется.","38":"Днем над скинией стояло облако Господне, а ночью в этом облаке горел огонь – и это видели все израильтяне. Так было всегда во время их странствий."}};
